      "path": "src/client/studio-view.tsx",
      "content": "import { memo, useCallback, useEffect, useLayoutEffect, useMemo, useRef, useState, useSyncExternalStore, type ChangeEvent, type FC } from 'react'\nimport type { ImageAttachmentRef, ImageMediaType } from '@deepseek-ai/dsh-attachment'\nimport {\n  AlertTriangle,\n  BookmarkPlus,\n  Check,\n  ChevronDown,\n  ChevronLeft,\n  ChevronRight,\n  Clipboard,\n  Copy,\n  Download,\n  Expand,\n  FileText,\n  Frame,\n  Heart,\n  ImagePlus,\n  Info,\n  LoaderCircle,\n  PanelLeft,\n  PanelLeftClose,\n  PanelRight,\n  PanelRightClose,\n  PencilLine,\n  Plus,\n  RefreshCw,\n  Sparkles,\n  Star,\n  Trash2,\n  Upload,\n  X,\n  ZoomIn,\n  ZoomOut,\n} from 'lucide-react'\nimport { DELETE_ROUTE, SAVE_WORKSPACE_ROUTE, STUDIO_ROUTE, thumbUrlFor, isSubscriptionProvider, studioWatermarkCapability, studioModelForMode, studioModelOptionsForMode, studioTargetKey, type CloudImageProvider, type StudioConfigResponse, type StudioGenerateResponse, type StudioGeneratedItem, type StudioProvider, type StudioProviderProfile, type StudioReference, type StudioWatermark } from '../shared.js'\nimport { deleteGalleryItem, getGalleryItems, subscribeGallery, toggleFavoriteGalleryItem, type GalleryItem, saveFavoritePrompt, getFavoritePrompts, deleteFavoritePrompt, subscribeFavorites, addFavoriteFolder, getFavoriteFolders, deleteFavoriteFolder, moveFavoritePrompt, updateFavoritePrompt, type FavoritePrompt, type FavoriteFolder } from './gallery-store.js'\nimport { persistGalleryRecord } from './gallery-media.js'\nimport { imageVersionKey } from './image-result-node.js'\nimport { studioSession, type StudioViewState } from './studio-session.js'\nimport { copyImageBlob, downloadBlobUrl, formatRelativeTime } from './browser-image-utils.js'\nimport { buildComparisonTargets, comparisonOptionUnion, comparisonOutputOptions, initialComparisonProviders } from './multi-model-compare.js'\nimport { WatermarkControl } from './watermark-control.js'\nimport { clearStudioTlCanvases, StudioTlCanvas } from './tl/studio-tl-canvas.js'\nimport { pushTlLandings } from './tl/tl-canvas-bridge.js'\nimport { GalleryCanvasButton } from './tl/gallery-canvas-button.js'\nimport { startGalleryImageDrag } from './tl/gallery-image-transfer.js'\nimport type { LocaleService } from './gallery-view.js'\nimport {\n  BatchCanvasItem,\n  FavoriteFolderBar,\n  FieldSelect,\n  RecentItem,\n  extension,\n  fileToBase64,\n  hasSubscriptionRatioMismatch,\n  localizeQualityOptions,\n  localizeRatioOptions,\n  messageOf,\n  useAttachmentImage,\n  useInView,\n  type RecentItemActions,\n} from './studio-helpers.js'\nimport { evictAttachmentCache, fetchAttachmentBlob } from './image-cache.js'\nimport { PROVIDER_DEFAULT_QUALITY } from '../openai-output.js'\n\n\nconst PAGE_SIZE = 12\nconst MODEL_DISCOVERY_POLL_MS = 1_000\nconst MODEL_DISCOVERY_WINDOW_MS = 12_000\n\n/** Below this workbench width the recent-generations rail folds automatically. */\nconst WORKBENCH_NARROW_WIDTH = 560\n\ntype Mode = 'generate' | 'edit'\ntype BatchKind = StudioViewState['batchKind'] & string\n\nexport interface StudioReferenceItem {\n  id: string\n  attachment?: ImageAttachmentRef\n  file?: File\n  previewUrl: string\n}\n\nconst COPY = {\n  zh: {\n    title: '云端生图工作台', configured: 'API 已配置', unconfigured: '未配置', recent: '最近生成', empty: '暂无生成历史',\n    railTabRecent: '最新生成', railTabFavorites: '收藏', favImages: '收藏图片', favPrompts: '收藏提示词',\n    favNewFolder: '新建文件夹', favFolderPlaceholder: '文件夹名称', favCreate: '创建', favCancel: '取消',\n    favMoveTo: '移动到文件夹', favNoFolder: '未分组', favMove: '移动', favDeleteFolder: '删除文件夹',\n    favEditPrompt: '编辑提示词', favUse: '使用', favSave: '保存', favEditPromptPlaceholder: '输入提示词内容…', favFolder: '所属文件夹',\n    favEmptyImages: '在图片操作区点「收藏」后，图片会显示在这里', favEmptyPrompts: '点提示词输入框旁的「☆ 收藏」后，提示词会显示在这里',\n    favoritePrompt: '收藏提示词', favActionShort: '收藏', favPromptSaved: '已收藏提示词',\n    favPromptApplied: '已填入提示词', favRefApplied: '已加入参考图', favSaveFailed: '收藏失败，请重试',\n    generate: '文生图', edit: '图生图', reference: '参考图', optional: '选填', upload: '点击或拖拽图片到此处',\n    uploadHint: '支持 JPG / PNG / WebP / GIF，最大 10MB（最多 5 张）', prompt: '提示词 Prompt', clear: '清空', promptPlaceholder: '描述主体、构图、风格、光线与需要出现的文字…（支持 Ctrl+Enter 快捷生成）',\n    provider: 'Provider', model: 'Model', ratio: '比例', quality: '清晰度', subscriptionParameterHint: '所选比例会自动补充到生成提示词中；实际尺寸和清晰度仍由 ChatGPT 决定，请以生成结果为准。', subscriptionRatioMismatch: 'ChatGPT 订阅未按所选比例出图，请查看实际尺寸。', start: '开始生成', generating: '正在生成…', cancelGenerate: '取消生成',\n    count: '生成数量', countUnit: '{n} 张', partialSuccess: '已生成 {success} 张图片，{failed} 张失败', generatingCount: '正在生成（共 {count} 张）…',\n    batchResult: '本次生成（共 {count} 张）',\n    singleModel: '单模型', compareModels: '多模型对比', compareHint: '相同提示词，同时交给多个模型', compareSelect: '选择模型', compareSelected: '已选 {count} 个模型',\n    compareNeedTwo: '请至少选择两个已配置模型', compareParameterHint: '不支持所选参数的模型会自动使用默认值', compareAdjusted: '已适配', comparePartial: '{success} 个模型生成成功，{failed} 个失败',\n    comparing: '正在对比（共 {count} 个模型）…', compareStart: '开始对比',\n    saveToGallery: '保存', saveSelected: '保存({count})', savedToGallery: '已保存到画廊', savedSelected: '已保存 {count} 张图片', inGallery: '已保存', needSelectResult: '请先勾选要保存的图片',\n    retry: '重新加载', configLoadFailed: '工作台配置加载失败，请检查服务后重试。',\n    noProvider: '请先在设置中配置至少一个云端图像 Provider 的 API Key。', selectConfigured: '该 Provider 尚未配置，请先到设置中配置 API Key。',\n    needPrompt: '请输入提示词', needReference: '请先添加至少一张参考图', result: '本次结果', continueEdit: '继续编辑（垫图）', regenerate: '再次生成',\n    copy: '复制', copied: '已复制到剪贴板', copyFailed: '复制失败', download: '下载', remove: '删除', fit: '适应窗口', infiniteCanvas: '无限画布', loading: '正在读取图片…', generationFailed: '生成失败', gatewayTimeout: '请求被反向代理中断（超时）：请重试；反复出现需调大代理超时或换直连网络', requestFailed: '请求失败（HTTP {status}）',\n    selectHistory: '从左侧选择一张图片，或在右侧开始新的生成。', created: '生成时间', elapsed: '耗时', dimensions: '尺寸', output: '输出参数',\n    closeReference: '移除参考图', uploadInvalid: '请选择有效的图片文件（最大 10MB）', uploadUnreadable: '部分图片读取失败，请重新选择后再试', imageLoadFailed: '图片读取失败',\n    fullscreen: '大图全屏', close: '关闭', copyPpt: '复制 Prompt', copiedPrompt: '已复制 Prompt', copiedImage: '已复制图片',\n    favorite: '收藏', favorited: '已收藏', favoriteAdded: '已添加到收藏', favoriteRemoved: '已取消收藏', gallerySaveFailed: '保存到图库失败，请重试',\n    loadMore: '加载更多 ({n})', deleteModalTitle: '从图库删除', deleteModalDesc: '确定从图库中删除这张图片吗？（原聊天记录不会受影响）',\n    deleteWorkspaceFilesLabel: '同时删除工作区本地文件', confirm: '确定删除', cancel: '取消', deletedToast: '已从图库删除',\n    referencesCount: '参考图 ({current}/{max})', addMoreRef: '+ 添加', maxReferencesExceeded: '最多支持添加 {max} 张参考图',\n    newGeneration: '新建生成', new: '新建',\n    configuredCount: 'API 已配置 · {count}', unconfiguredStatus: 'API 未配置', providerStatus: '云端提供商与模型状态',\n    configuredSplit: 'API {api} · 订阅 {sub}', subSignedIn: '已登录', subSignedOut: '未登录',\n    collapseSidebar: '折叠最近生成', expandSidebar: '展开最近生成',\n    collapseGenerate: '折叠生成面板', expandGenerate: '展开生成面板', generatePanel: '生成面板',\n    findInspiration: '找灵感',\n    infiniteCanvasHint: '无限画布与侧边栏会话联动，才是完整功能。打开 DSH 右侧边栏的「图像工作台」即可解锁。',\n    clearCanvas: '清空画布', clearCanvasDescription: '将永久清空所有画布页面的内容、图片资产和撤销历史。画廊已保存的卡片及原图不受影响，此操作无法撤销。', canvasCleared: '画布已清空，画廊不受影响',\n  },\n  en: {\n    title: 'Cloud Image Studio', configured: 'API configured', unconfigured: 'Not configured', recent: 'Recent generations', empty: 'No generated images yet',\n    railTabRecent: 'Latest', railTabFavorites: 'Favorites', favImages: 'Favorite images', favPrompts: 'Favorite prompts',\n    favNewFolder: 'New folder', favFolderPlaceholder: 'Folder name', favCreate: 'Create', favCancel: 'Cancel',\n    favMoveTo: 'Move to folder', favNoFolder: 'Unfiled', favMove: 'Move', favDeleteFolder: 'Delete folder',\n    favEditPrompt: 'Edit prompt', favUse: 'Use', favSave: 'Save', favEditPromptPlaceholder: 'Prompt text…', favFolder: 'Folder',\n    favEmptyImages: 'Click Favorite on an image; favorited images appear here', favEmptyPrompts: 'Click ☆ Save beside the prompt box',\n    favoritePrompt: 'Save prompt', favActionShort: 'Save', favPromptSaved: 'Prompt saved',\n    favPromptApplied: 'Prompt applied', favRefApplied: 'Reference added', favSaveFailed: 'Could not save; please retry',\n    generate: 'Text to image', edit: 'Image to image', reference: 'Reference image', optional: 'optional', upload: 'Click or drop images here',\n    uploadHint: 'JPG / PNG / WebP / GIF, up to 10MB (max 5)', prompt: 'Prompt', clear: 'Clear', promptPlaceholder: 'Describe the subject, composition, style, lighting, and exact text… (Ctrl+Enter to generate)',\n    provider: 'Provider', model: 'Model', ratio: 'Aspect ratio', quality: 'Quality', subscriptionParameterHint: 'The selected aspect ratio is automatically added to the generation prompt. ChatGPT still determines the final dimensions and quality; check the generated result.', subscriptionRatioMismatch: 'ChatGPT subscription returned a different aspect ratio. Check the actual dimensions.', start: 'Generate', generating: 'Generating…', cancelGenerate: 'Cancel',\n    count: 'Number of images', countUnit: '{n}', partialSuccess: 'Generated {success} images, {failed} failed', generatingCount: 'Generating ({count} images)…',\n    batchResult: 'Generated {count} images',\n    singleModel: 'Single model', compareModels: 'Compare models', compareHint: 'Send the same prompt to multiple models', compareSelect: 'Choose models', compareSelected: '{count} models selected',\n    compareNeedTwo: 'Select at least two configured models', compareParameterHint: 'Unsupported settings use each model’s default', compareAdjusted: 'Adjusted', comparePartial: '{success} models succeeded, {failed} failed',\n    comparing: 'Comparing {count} models…', compareStart: 'Compare models',\n    saveToGallery: 'Save to Gallery', saveSelected: 'Save selected ({count})', savedToGallery: 'Saved to Gallery', savedSelected: 'Saved {count} images', inGallery: 'In Gallery', needSelectResult: 'Select images to save first',\n    retry: 'Retry', configLoadFailed: 'Failed to load studio configuration.',\n    noProvider: 'Configure an API key for at least one cloud image provider in Settings.', selectConfigured: 'This provider is not configured. Add its API key in Settings first.',\n    needPrompt: 'Enter a prompt', needReference: 'Add at least one reference image first', result: 'Current result', continueEdit: 'Continue editing', regenerate: 'Generate again',\n    copy: 'Copy', copied: 'Copied to clipboard', copyFailed: 'Copy failed', download: 'Download', remove: 'Delete', fit: 'Fit', infiniteCanvas: 'Infinite canvas', loading: 'Loading image…', generationFailed: 'Generation failed', gatewayTimeout: 'The reverse proxy cut the request (timeout): retry; if it repeats, raise the proxy timeout or use a direct network.', requestFailed: 'Request failed (HTTP {status})',\n    selectHistory: 'Select an image on the left, or start a new generation on the right.', created: 'Created', elapsed: 'Elapsed', dimensions: 'Dimensions', output: 'Output',\n    closeReference: 'Remove reference', uploadInvalid: 'Choose a valid image file up to 10MB.', uploadUnreadable: 'Some images could not be read; pick them again.', imageLoadFailed: 'Could not load image',\n    fullscreen: 'Fullscreen', close: 'Close', copyPpt: 'Copy Prompt', copiedPrompt: 'Prompt copied', copiedImage: 'Image copied',\n    favorite: 'Favorite', favorited: 'Favorited', favoriteAdded: 'Added to favorites', favoriteRemoved: 'Removed from favorites', gallerySaveFailed: 'Failed to save to the gallery, please retry',\n    loadMore: 'Load more ({n})', deleteModalTitle: 'Delete from gallery', deleteModalDesc: 'Remove this image from the local gallery? (Chat history remains unaffected)',\n    deleteWorkspaceFilesLabel: 'Also delete local workspace files', confirm: 'Delete', cancel: 'Cancel', deletedToast: 'Deleted from gallery',\n    referencesCount: 'References ({current}/{max})', addMoreRef: '+ Add', maxReferencesExceeded: 'Up to {max} reference images allowed',\n    newGeneration: 'New generation', new: 'New',\n    configuredCount: 'API configured · {count}', unconfiguredStatus: 'Not configured', providerStatus: 'Provider & Model Status',\n    configuredSplit: 'API {api} · Sub {sub}', subSignedIn: 'Signed in', subSignedOut: 'Signed out',\n    collapseSidebar: 'Collapse sidebar', expandSidebar: 'Expand recent list',\n    collapseGenerate: 'Collapse generate panel', expandGenerate: 'Expand generate panel', generatePanel: 'Generate',\n    findInspiration: 'Find inspiration',\n    infiniteCanvasHint: 'The infinite canvas is at its best when linked with the sidebar conversation. Open Image Studio from the DSH right sidebar to unlock the full experience.',\n    clearCanvas: 'Clear canvas', clearCanvasDescription: 'Permanently clear all canvas pages, image assets, and undo history. Saved gallery cards and original images are unaffected. This cannot be undone.', canvasCleared: 'Canvas cleared. Gallery unchanged.',\n  },\n} as const\n\ntype CopyKey = keyof typeof COPY.zh\n\n/** localStorage flag remembering that the one-time infinite-canvas hint was dismissed. */\nconst INFINITE_CANVAS_HINT_KEY = 'dsh-ig-infinite-canvas-hint-dismissed'\n\nexport interface StudioWorkspaceProps {\n  workspaceId?: string | undefined\n  path?: string | undefined\n  title?: string | undefined\n  sessionIds?: readonly string[] | undefined\n}\n\n/**\n * The selection after the gallery reloaded: the fresh record of a saved item,\n * null for a saved item that was deleted, and an unsaved result unchanged.\n */\nexport function keepSelection(current: GalleryItem, next: readonly GalleryItem[], previousIds: ReadonlySet<string> | undefined): GalleryItem | null {\n  const fresh = next.find(item => item.id === current.id)\n  if (fresh !== undefined) return fresh\n  return previousIds?.has(current.id) === true ? null : current\n}\n\nexport const StudioView: FC<{\n  locale?: LocaleService | undefined\n  /** Host credential-change notifier; re-reads provider sign-in state silently. */\n  credentialEvents?: { listen(callback: () => void): () => void } | undefined\n  workspace?: StudioWorkspaceProps | null | undefined\n  initialPrompt?: string | undefined\n  /** Reference image applied once on arrival (e.g. an inspiration card used as 图生图 input). */\n  initialReference?: File | undefined\n  /**\n   * Canvas surface opened first: 'preview' (single-image viewer, the default)\n   * or 'infinite' (the tldraw editor). The right-sidebar variant opens the\n   * infinite canvas directly - mirroring chat-generated images while the\n   * native conversation runs beside it is the point of the split.\n   */\n  initialCanvasSurface?: 'preview' | 'infinite' | undefined\n  /**\n   * Show the one-time hint banner above the infinite canvas. Only the\n   * conversation-tab seat (no chat running beside the canvas) needs it - the\n   * right-sidebar variant IS the full experience, so the hint would be noise.\n   */\n  showInfiniteCanvasHint?: boolean\n  onInitialPromptApplied?(): void\n  onInitialReferenceApplied?(): void\n  onOpenInspiration?(): void\n}> = ({ locale, credentialEvents, workspace, initialPrompt, initialReference, initialCanvasSurface, showInfiniteCanvasHint, onInitialPromptApplied, onInitialReferenceApplied, onOpenInspiration }) => {\n  const [lang, setLang] = useState<'zh' | 'en'>(() => locale?.getSnapshot?.().active?.startsWith('en') ? 'en' : 'zh')\n  const [config, setConfig] = useState<StudioConfigResponse | null>(null)\n  const [configLoading, setConfigLoading] = useState(true)\n  const [configError, setConfigError] = useState<string | null>(null)\n  const [items, setItems] = useState<GalleryItem[]>([])\n  /** Which rail tab is showing: generation history or the favorites rail. */\n  const [railTab, setRailTab] = useState<'recent' | 'favorites'>('recent')\n  const [favPrompts, setFavPrompts] = useState<FavoritePrompt[]>([])\n  const [favFolders, setFavFolders] = useState<FavoriteFolder[]>([])\n  const [activePromptFolder, setActivePromptFolder] = useState('')\n  const [folderDraft, setFolderDraft] = useState<{ kind: 'prompt' } | null>(null)\n  const [folderDraftName, setFolderDraftName] = useState('')\n  const [editingPrompt, setEditingPrompt] = useState<FavoritePrompt | null>(null)\n  const [editPromptText, setEditPromptText] = useState('')\n  const [editPromptFolder, setEditPromptFolder] = useState('')\n  const [movingFav, setMovingFav] = useState<{ kind: 'prompt', id: string, folderId: string | undefined } | null>(null)\n  const [sidebarCollapsed, setSidebarCollapsed] = useState(false)\n  /** Manual-only collapse for the right generate form; the form stays put in\n   *  narrow seats because it is the primary generation surface. Starts folded\n   *  when the studio opens straight into the infinite canvas. */\n  // The sidebar variant opens on the infinite canvas; a carried-in prompt draft\n  // still needs its generate form visible.\n  const [generateCollapsed, setGenerateCollapsed] = useState(initialCanvasSurface === 'infinite' && initialPrompt === undefined)\n  /** Workbench root, observed so a narrow column (right sidebar) can fold the recent rail. */\n  const workbenchRootRef = useRef<HTMLElement | null>(null)\n  /** Set once the user toggles the rail by hand; auto-folding then stands down for this mount. */\n  const railToggledByUserRef = useRef(false)\n  const [visibleLimit, setVisibleLimit] = useState(30)\n  const [favoriteLimit, setFavoriteLimit] = useState(60)\n  // Stable dispatchers keep memoized rail tiles from re-rendering on every\n  // parent update (prompt typing, selection, tab switches).\n  const railActionsRef = useRef<RecentItemActions | null>(null)\n  const railActions = useMemo<RecentItemActions>(() => ({\n    select: item => railActionsRef.current?.select(item),\n    favorite: item => railActionsRef.current?.favorite(item),\n    toast: message => railActionsRef.current?.toast(message),\n  }), [])\n  // The session outlives this component (#99): a generation keeps running when\n  // the user switches views, and the results on screen come back on return.\n  const session = useMemo(() => studioSession(initialCanvasSurface ?? 'preview'), [initialCanvasSurface])\n  const sessionState = useSyncExternalStore(session.subscribe, session.getSnapshot)\n  const restoredView = useMemo(() => session.view(), [session])\n  const [selected, setSelected] = useState<GalleryItem | null>(() => restoredView?.selected ?? null)\n  const [mode, setMode] = useState<Mode>('generate')\n  const [provider, setProvider] = useState<StudioProvider>('google')\n  const [channel, setChannel] = useState<string | undefined>(undefined)\n  const [model, setModel] = useState('')\n  const [ratio, setRatio] = useState('1:1')\n  const [quality, setQuality] = useState('1K')\n  const [resolution, setResolution] = useState('1K')\n  const [generationQuality, setGenerationQuality] = useState(PROVIDER_DEFAULT_QUALITY)\n  const [watermark, setWatermark] = useState<StudioWatermark>('default')\n  const [prompt, setPrompt] = useState('')\n  const [references, setReferences] = useState<StudioReferenceItem[]>([])\n  const [count, setCount] = useState(1)\n  const [currentBatch, setCurrentBatch] = useState<GalleryItem[] | null>(() => restoredView?.currentBatch ?? null)\n  const [selectedBatchIds, setSelectedBatchIds] = useState<string[]>(() => restoredView?.selectedBatchIds ?? [])\n  const [batchKind, setBatchKind] = useState<BatchKind | null>(() => restoredView?.batchKind ?? null)\n  const [comparisonEnabled, setComparisonEnabled] = useState(false)\n  const [comparisonProviderKeys, setComparisonProviderKeys] = useState<string[]>([])\n  const isGenerating = sessionState.generating\n  const [error, setError] = useState<string | null>(null)\n  const [notice, setNotice] = useState<string | null>(null)\n\n  // Interactive Pan-Zoom Viewport State\n  const [zoom, setZoom] = useState(100)\n  const [fit, setFit] = useState(true)\n  const [offset, setOffset] = useState<{ x: number; y: number }>({ x: 0, y: 0 })\n  const [isDragging, setIsDragging] = useState(false)\n  const dragStartRef = useRef<{ x