       ))}\n                      </div>\n                      {list.length > favoriteLimit && (\n                        <button type=\"button\" className=\"dsh-ig-load-more\" onClick={() => setFavoriteLimit(limit => limit + 60)}>\n                          {t('loadMore', { n: String(list.length - favoriteLimit) })}\n                        </button>\n                      )}\n                    </>\n                  )\n                })()}\n                <div className=\"dsh-ig-fav-section-label\">\n                  <span>{t('favPrompts')}</span>\n                  <button type=\"button\" className=\"dsh-ig-fav-folder-add\" onClick={() => { setFolderDraft({ kind: 'prompt' }); setFolderDraftName('') }} title={t('favNewFolder')}>＋</button>\n                </div>\n                <FavoriteFolderBar\n                  folders={favFolders.filter(folder => folder.kind === 'prompt')}\n                  active={activePromptFolder}\n                  onSelect={id => setActivePromptFolder(id === activePromptFolder ? '' : id)}\n                  onDelete={id => void deleteFavoriteFolder(id)}\n                  deleteLabel={t('favDeleteFolder')}\n                />\n                {folderDraft?.kind === 'prompt' && (\n                  <div className=\"dsh-ig-fav-folder-draft\">\n                    <input value={folderDraftName} placeholder={t('favFolderPlaceholder')} onChange={e => setFolderDraftName(e.target.value)} onKeyDown={e => { if (e.key === 'Enter') void createFavFolder() }} />\n                    <button type=\"button\" onClick={() => void createFavFolder()}>{t('favCreate')}</button>\n                    <button type=\"button\" onClick={() => setFolderDraft(null)}>{t('favCancel')}</button>\n                  </div>\n                )}\n                {(() => {\n                  const list = favPrompts.filter(fav => activePromptFolder === '' || fav.folderId === activePromptFolder)\n                  if (list.length === 0) return <div className=\"dsh-ig-fav-empty\"><PencilLine size={18} /><span>{t('favEmptyPrompts')}</span></div>\n                  return <div className=\"dsh-ig-fav-prompts\">\n                    {list.map(fav => (\n                      <div key={fav.id} className=\"dsh-ig-fav-prompt\">\n                        <button type=\"button\" className=\"dsh-ig-fav-prompt-text\" title={fav.text} onClick={() => openPromptEditor(fav)}>{fav.text}</button>\n                        <button type=\"button\" className=\"dsh-ig-fav-del\" title={t('remove')} onClick={() => void deleteFavoritePrompt(fav.id)}><X size={11} /></button>\n                      </div>\n                    ))}\n                  </div>\n                })()}\n              </div>\n            )}\n          </aside>\n        )}\n\n        {(editingPrompt !== null || movingFav !== null) && (\n          <div className=\"dsh-ig-fav-dialog-wrap\" onClick={() => { setEditingPrompt(null); setMovingFav(null) }}>\n            <div className=\"dsh-ig-fav-dialog\" onClick={e => e.stopPropagation()}>\n              {editingPrompt !== null && (\n                <>\n                  <div className=\"dsh-ig-fav-dialog-title\">{t('favEditPrompt')}</div>\n                  <textarea className=\"dsh-ig-fav-dialog-textarea\" value={editPromptText} placeholder={t('favEditPromptPlaceholder')} onChange={e => setEditPromptText(e.target.value)} rows={5} />\n                  <label className=\"dsh-ig-fav-dialog-folder-label\">{t('favFolder')}\n                    <select value={editPromptFolder} onChange={e => setEditPromptFolder(e.target.value)}>\n                      <option value=\"\">{t('favNoFolder')}</option>\n                      {favFolders.filter(folder => folder.kind === 'prompt').map(folder => <option key={folder.id} value={folder.id}>{folder.name}</option>)}\n                    </select>\n                  </label>\n                  <div className=\"dsh-ig-fav-dialog-actions\">\n                    <button type=\"button\" className=\"is-primary\" onClick={() => { void updateFavoritePrompt(editingPrompt.id, editPromptText).then(ok => { if (ok) void moveFavoritePrompt(editingPrompt.id, editPromptFolder === '' ? undefined : editPromptFolder) }); setEditingPrompt(null) }}>{t('favSave')}</button>\n                    <button type=\"button\" onClick={() => { applyFavoritePrompt({ ...editingPrompt, text: editPromptText }); setEditingPrompt(null) }}>{t('favUse')}</button>\n                    <button type=\"button\" onClick={() => { setMovingFav({ kind: 'prompt', id: editingPrompt.id, folderId: editingPrompt.folderId }); setEditingPrompt(null) }}>{t('favMove')}</button>\n                    <button type=\"button\" onClick={() => setEditingPrompt(null)}>{t('favCancel')}</button>\n                  </div>\n                </>\n              )}\n              {editingPrompt === null && movingFav !== null && (\n                <>\n                  <div className=\"dsh-ig-fav-dialog-title\">{t('favMoveTo')}</div>\n                  <div className=\"dsh-ig-fav-dialog-folders\">\n                    <button type=\"button\" onClick={() => { void doMoveFavorite(undefined); setMovingFav(null) }}>{t('favNoFolder')}</button>\n                    {favFolders.filter(folder => folder.kind === movingFav.kind).map(folder => (\n                      <button type=\"button\" key={folder.id} className={movingFav.folderId === folder.id ? 'is-current' : ''} onClick={() => { void doMoveFavorite(folder.id); setMovingFav(null) }}>{folder.name}</button>\n                    ))}\n                  </div>\n                  <div className=\"dsh-ig-fav-dialog-actions\">\n                    <button type=\"button\" onClick={() => setMovingFav(null)}>{t('favCancel')}</button>\n                  </div>\n                </>\n              )}\n            </div>\n          </div>\n        )}\n\n        <main className=\"dsh-ig-canvas-column\">\n          <div className=\"dsh-ig-canvas-toolbar\">\n            <div className=\"dsh-ig-canvas-toolbar-left\">\n              {sidebarCollapsed && (\n                <button\n                  type=\"button\"\n                  onClick={() => { railToggledByUserRef.current = true; setSidebarCollapsed(false) }}\n                  title={t('expandSidebar')}\n                >\n                  <PanelLeft size={14} />\n                  <span>{t('recent')}</span>\n                </button>\n              )}\n              <div className=\"dsh-ig-status-badge-wrap\">\n                <div className=\"dsh-ig-status-badge\">\n                  <span className={`dsh-ig-status-dot ${configuredCount > 0 ? 'is-ready' : 'is-muted'}`} />\n                  <span className=\"dsh-ig-status-text\">\n                    {configuredCount > 0\n                      ? (subscriptionSignedInCount > 0\n                          ? t('configuredSplit', { api: String(apiConfiguredCount), sub: String(subscriptionSignedInCount) })\n                          : t('configuredCount', { count: String(apiConfiguredCount) }))\n                      : t('unconfiguredStatus')}\n                  </span>\n                  <ChevronDown size={11} className=\"dsh-ig-status-arrow\" />\n                </div>\n                {config !== null && (\n                  <div className=\"dsh-ig-status-popover\">\n                    <div className=\"dsh-ig-status-popover-title\">{t('providerStatus')}</div>\n                    <ul className=\"dsh-ig-status-list\">\n                      {config.providers.map(p => (\n                        <li key={p.provider} className={p.configured ? 'is-configured' : 'is-missing'}>\n                          <div className=\"dsh-ig-status-item-name\">\n                            <strong>{p.label}</strong>\n                            <small>{studioModelForMode(p, mode)}</small>\n                          </div>\n                          <span className=\"dsh-ig-status-item-tag\">\n                            {isSubscriptionProvider(p.provider)\n                              ? (p.configured ? t('subSignedIn') : t('subSignedOut'))\n                              : (p.configured ? t('configured') : t('unconfigured'))}\n                          </span>\n                        </li>\n                      ))}\n                    </ul>\n                  </div>\n                )}\n              </div>\n            </div>\n            {/* Canvas-surface toggle sits centered so the entry point to the\n             * infinite canvas reads at a glance in both surfaces. */}\n            <div className=\"dsh-ig-canvas-toolbar-center\">\n              <button\n                type=\"button\"\n                className={canvasSurface === 'infinite' ? 'is-active' : ''}\n                onClick={() => {\n                  if (canvasSurface === 'infinite') {\n                    // Back to preview: restore the panel exactly as it was\n                    // before the canvas folded it.\n                    setGenerateCollapsed(generatePanelBeforeInfiniteRef.current)\n                    setCanvasSurface('preview')\n                    return\n                  }\n                  // Into the infinite canvas: fold the generate panel so the\n                  // surface gets the full width; reopening restores it.\n                  generatePanelBeforeInfiniteRef.current = generateCollapsed\n                  setGenerateCollapsed(true)\n                  setCanvasSurface('infinite')\n                }}\n                title={t('infiniteCanvas')}\n              >\n                <Frame size={14} />\n                <span>{t('infiniteCanvas')}</span>\n              </button>\n              {/* Preview-only view controls ride the center cluster too, so\n               * fit/zoom live beside the surface toggle instead of being\n               * buried among the right-side actions. */}\n              {canvasSurface === 'preview' && (<>\n                <span className=\"dsh-ig-toolbar-divider\" />\n                <button type=\"button\" className={fit ? 'is-active' : ''} onClick={resetFit}>{t('fit')} <ChevronDown size={13} /></button>\n                <button type=\"button\" onClick={() => { setFit(false); setZoom(value => Math.max(25, value - 25)) }} title=\"Zoom out\"><ZoomOut size={16} /></button>\n                <span className=\"dsh-ig-zoom-display\">{fit ? 'AUTO' : `${Math.round(zoom)}%`}</span>\n                <button type=\"button\" onClick={() => { setFit(false); setZoom(value => Math.min(500, value + 25)) }} title=\"Zoom in\"><ZoomIn size={16} /></button>\n              </>)}\n            </div>\n            <div className=\"dsh-ig-canvas-toolbar-right\">\n              {canvasSurface === 'infinite' && (\n                <button type=\"button\" onClick={() => setShowClearCanvasModal(true)} title={t('clearCanvas')}>\n                  <Trash2 size={14} /><span>{t('clearCanvas')}</span>\n                </button>\n              )}\n              {canvasSurface === 'preview' && selected !== null && (\n                <button type=\"button\" onClick={startNew} title={t('newGeneration')}>\n                  <Plus size={13} />\n                  <span>{t('newGeneration')}</span>\n                </button>\n              )}\n              {canvasSurface === 'preview' && (\n                <button type=\"button\" onClick={() => setLightboxOpen(true)} title={t('fullscreen')} disabled={selected === null}><Expand size={16} /></button>\n              )}\n              {generateCollapsed && (\n                <button\n                  type=\"button\"\n                  onClick={() => { setGenerateCollapsed(false) }}\n                  title={t('expandGenerate')}\n                >\n                  <PanelRight size={14} />\n                  <span>{t('generatePanel')}</span>\n                </button>\n              )}\n            </div>\n          </div>\n          {canvasSurface === 'infinite' && showInfiniteCanvasHint && !canvasHintDismissed && (\n            <div className=\"dsh-ig-canvas-hint\">\n              <Info size={14} />\n              <span>{t('infiniteCanvasHint')}</span>\n              <button type=\"button\" onClick={dismissCanvasHint} title={t('close')} aria-label={t('close')}>\n                <X size={13} />\n              </button>\n            </div>\n          )}\n          {canvasSurface === 'infinite' ? (\n            <StudioTlCanvas lang={lang} />\n          ) : (\n          <div\n            className={`dsh-ig-canvas ${isDragging ? 'is-dragging' : ''}`}\n            ref={canvasRef}\n            onMouseDown={handleCanvasMouseDown}\n            onDoubleClick={resetFit}\n          >\n            {isGenerating ? (\n              <div className=\"dsh-ig-generating-state\">\n                <div className=\"dsh-ig-generation-orbit\"><Sparkles size={28} /></div>\n                <strong>{comparisonEnabled ? t('comparing', { count: String(comparisonTargets.length) }) : count > 1 ? t('generatingCount', { count: String(count) }) : t('generating')}</strong>\n                <span>{comparisonEnabled ? comparisonTargets.map(target => target.profile.label).join(' · ') : `${activeProfile?.label ?? ''} · ${requestModel}`}</span>\n              </div>\n            ) : currentBatch && currentBatch.length > 1 ? (\n              <div\n                className=\"dsh-ig-canvas-cluster\"\n                data-count={currentBatch.length}\n                style={{\n                  transform: `translate(${offset.x}px, ${offset.y}px) scale(${zoom / 100})`,\n                  transformOrigin: 'center center',\n                  transition: isDragging ? 'none' : 'transform 0.08s ease-out',\n                }}\n              >\n                {currentBatch.map((batchItem, index) => (\n                  <BatchCanvasItem\n                    key={batchItem.id}\n                    item={batchItem}\n                    index={index}\n                    badge={batchKind === 'multi-model' ? batchItem.model : undefined}\n                    isActive={selected?.id === batchItem.id}\n                    isChecked={selectedBatchIds.includes(batchItem.id)}\n                    onSelect={() => {\n                      if (!hasDraggedRef.current) {\n                        setSelected(batchItem)\n                        setSelectedBatchIds(current => current.includes(batchItem.id)\n                          ? current.filter(id => id !== batchItem.id)\n                          : [...current, batchItem.id])\n                      }\n                    }}\n                  />\n                ))}\n              </div>\n            ) : selected === null ? (\n              <div className=\"dsh-ig-canvas-empty\"><ImagePlus size={36} /><span>{t('selectHistory')}</span></div>\n            ) : image.loading ? (\n              <>\n                <img\n                  className=\"dsh-ig-canvas-thumb\"\n                  src={thumbUrlFor(selected.attachment)}\n                  alt={selected.prompt}\n                  draggable={false}\n                  style={{\n                    ...(selected.attachment.width && selected.attachment.height\n                      ? { width: String(selected.attachment.width) + 'px', height: String(selected.attachment.height) + 'px' }\n                      : {}),\n                    transform: `translate(${offset.x}px, ${offset.y}px) scale(${zoom / 100})`,\n                    transformOrigin: 'center center',\n                    transition: isDragging ? 'none' : 'transform 0.08s ease-out',\n                  }}\n                />\n                <div className=\"dsh-ig-canvas-loading-pill\"><LoaderCircle className=\"dsh-ig-spin\" size={16} /><span>{t('loading')}</span></div>\n              </>\n            ) : image.url !== null ? (\n              <img\n                src={image.url}\n                alt={selected.prompt}\n                draggable={false}\n                onClick={handleImageClick}\n                style={{\n                  transform: `translate(${offset.x}px, ${offset.y}px) scale(${zoom / 100})`,\n                  transformOrigin: 'center center',\n                  transition: isDragging ? 'none' : 'transform 0.08s ease-out',\n                }}\n              />\n            ) : (\n              <div className=\"dsh-ig-canvas-empty\"><ImagePlus size={32} /><span>{t('imageLoadFailed')}</span></div>\n            )}\n          </div>\n          )}\n          {selected !== null && canvasSurface === 'preview' && <>\n            <div className=\"dsh-ig-result-strip\"><span>{t('result')}</span><div><button type=\"button\" onClick={() => void continueEdit()}><PencilLine size={15} />{t('continueEdit')}</button><button type=\"button\" onClick={() => prepareRegeneration(selected)}><RefreshCw size={15} />{t('regenerate')}</button></div></div>\n            <div className=\"dsh-ig-result-actions\">\n              <p>{selected.prompt}</p>\n              <div>\n                <button\n                  type=\"button\"\n                  className={`dsh-ig-save-gallery-btn ${saveSelectionComplete ? 'is-saved' : ''}`}\n                  onClick={() => void handleSaveToGallery()}\n                  title={saveButtonLabel}\n                  disabled={saveSelectionComplete}\n                >\n                  {saveSelectionComplete ? <Check size={15} /> : <BookmarkPlus size={15} />}\n                  <span>{saveButtonLabel}</span>\n                </button>\n                <button\n                  type=\"button\"\n                  onClick={() => void toggleFavorite()}\n                  title={selected.isFavorite ? t('favorited') : t('favorite')}\n                >\n                  <Heart\n                    size={15}\n                    fill={selected.isFavorite ? '#ef4444' : 'none'}\n                    color={selected.isFavorite ? '#ef4444' : 'currentColor'}\n                  />\n                  <span>{selected.isFavorite ? t('favorited') : t('favorite')}</span>\n                </button>\n                <button type=\"button\" onClick={() => void copySelected()}><Clipboard size={15} /><span>{t('copy')}</span></button>\n                <button type=\"button\" onClick={downloadSelected}><Download size={15} /><span>{t('download')}</span></button>\n                <button type=\"button\" onClick={() => setShowDeleteModal(true)}><Trash2 size={15} /><span>{t('remove')}</span></button>\n              </div>\n            </div>\n            <div className=\"dsh-ig-result-meta\"><span>{formatRelativeTime(selected.createdAt, lang)}</span><span>{selected.provider}</span><span>{selected.model}</span><span>{selected.provider === 'chatgpt-sub' ? selected.output : selected.attachment.width && selected.attachment.height ? `${selected.attachment.width} × ${selected.attachment.height}` : '—'}</span>{hasSubscriptionRatioMismatch(selected) && <span>{t('subscriptionRatioMismatch')}</span>}</div>\n          </>}\n        </main>\n\n        {!generateCollapsed && (\n        <aside className=\"dsh-ig-generate-panel\">\n          <div className=\"dsh-ig-panel-title\">\n            <span>{t('generatePanel')}</span>\n            <button\n              type=\"button\"\n              className=\"dsh-ig-collapse-btn\"\n              onClick={() => { setGenerateCollapsed(true) }}\n              title={t('collapseGenerate')}\n            >\n              <PanelRightClose size={15} />\n            </button>\n          </div>\n          <div className=\"dsh-ig-generator-form\">\n            <div className=\"dsh-ig-mode-switch\"><button type=\"button\" className={mode === 'generate' ? 'is-active' : ''} onClick={() => setMode('generate')}><Sparkles size={15} />{t('generate')}</button><button type=\"button\" className={mode === 'edit' ? 'is-active' : ''} onClick={() => setMode('edit')}><ImagePlus size={15} />{t('edit')}</button></div>\n            {mode === 'edit' && (\n              <div className=\"dsh-ig-field\">\n                <div className=\"dsh-ig-field-label\">\n                  <label>\n                    {t('referencesCount', { current: String(references.length), max: String(maxReferences) })} <b>*</b>\n                  </label>\n                  {references.length > 0 && (\n                    <button type=\"button\" onClick={clearAllReferences}>\n                      {t('clear')}\n                    </button>\n                  )}\n                </div>\n\n                {references.length === 0 ? (\n                  <button\n                    type=\"button\"\n                    className={`dsh-ig-upload ${dragging ? 'is-dragging' : ''}`}\n                    onClick={() => fileInputRef.current?.click()}\n                    onDragOver={event => { event.preventDefault(); setDragging(true) }}\n                    onDragLeave={() => setDragging(false)}\n                    onDrop={event => {\n                      event.preventDefault()\n                      setDragging(false)\n                      void addReferenceFiles(event.dataTransfer.files)\n                    }}\n                  >\n                    <Upload size={20} />\n                    <strong>{t('upload')}</strong>\n                    <small>{t('uploadHint')}</small>\n                  </button>\n                ) : (\n                  <div className=\"dsh-ig-reference-grid\">\n                    {references.map((item, index) => (\n                      <div key={item.id} className=\"dsh-ig-reference-card\">\n                        <img src={item.previewUrl} alt={`Ref ${index + 1}`} />\n                        <button\n                          type=\"button\"\n                          title={t('closeReference')}\n                          onClick={() => removeReference(item.id)}\n                        >\n                          <X size={12} />\n                        </button>\n                      </div>\n                    ))}\n                    {references.length < maxReferences && (\n                      <button\n                        type=\"button\"\n                        className=\"dsh-ig-reference-add\"\n                        onClick={() => fileInputRef.current?.click()}\n                        title={t('upload')}\n                      >\n                        <Upload size={16} />\n                        <span>{t('addMoreRef')}</span>\n                      </button>\n                    )}\n                  </div>\n                )}\n                <input\n                  ref={fileInputRef}\n                  type=\"file\"\n                  multiple\n                  accept=\"image/png,image/jpeg,image/webp,image/gif\"\n                  hidden\n                  onChange={(event: ChangeEvent<HTMLInputElement>) => {\n                    void addReferenceFiles(event.target.files)\n                    event.target.value = ''\n                  }}\n                />\n              </div>\n            )}\n            <div className=\"dsh-ig-field\">\n              <div className=\"dsh-ig-field-label\"><label htmlFor=\"dsh-ig-prompt\">{t('prompt')} <b>*</b></label><span><button type=\"button\" className=\"dsh-ig-find-inspiration\" onClick={onOpenInspiration}><Sparkles size={11} />{t('findInspiration')}</button><button type=\"button\" className=\"dsh-ig-fav-save-btn\" onClick={() => void handleFavoritePrompt()} title={t('favoritePrompt')}><Star size={12} />{t('favActionShort')}</button><button type=\"button\" onClick={() => setPrompt('')}>{t('clear')}</button></span></div>\n              <textarea\n                id=\"dsh-ig-prompt\"\n                value={prompt}\n                onChange={event => setPrompt(event.target.value)}\n                onKeyDown={event => {\n                  if (event.nativeEvent.isComposing) return\n                  if ((event.ctrlKey || event.metaKey) && event.key === 'Enter') {\n                    event.preventDefault()\n                    if (!isGenerating && config !== null && prompt.trim().length > 0) void submit()\n                  }\n                }}\n                placeholder={t('promptPlaceholder')}\n              />\n              <small>{prompt.length}</small>\n            </div>\n            {config === null ? (\n              configLoading ? (\n                <div className=\"dsh-ig-form-loading\"><LoaderCircle className=\"dsh-ig-spin\" size={18} /></div>\n              ) : (\n                <div className=\"dsh-ig-config-error\">\n                  <p>{configError ?? t('configLoadFailed')}</p>\n                  <button type=\"button\" onClick={() => void loadConfig()}><RefreshCw size={13} /><span>{t('retry')}</span></button>\n                </div>\n              )\n            ) : <>\n              {comparisonProfiles.length >= 2 && (\n                <div className=\"dsh-ig-generation-kind\" role=\"group\" aria-label={t('compareModels')}>\n                  <button type=\"button\" className={!comparisonEnabled ? 'is-active' : ''} onClick={() => toggleComparison(false)}>{t('singleModel')}</button>\n                  <button type=\"button\" className={comparisonEnabled ? 'is-active' : ''} onClick={() => toggleComparison(true)}><Copy size={13} />{t('compareModels')}</button>\n                </div>\n              )}\n              {comparisonEnabled ? <>\n                <div className=\"dsh-ig-compare-box\">\n                  <div className=\"dsh-ig-compare-heading\">\n                    <div><strong>{t('compareSelect')}</strong><small>{t('compareHint')}</small></div>\n                    <span>{t('compareSelected', { count: String(comparisonTargets.length) })}</span>\n                  </div>\n                  <div className=\"dsh-ig-model-checks\">\n                    {comparisonProfiles.map(item => {\n                      const targetKey = studioTargetKey(item.provider, item.channel)\n                      const target = comparisonTargets.find(candidate => studioTargetKey(candidate.profile.provider, candidate.profile.channel) === targetKey)\n                      return (\n                        <button key={targetKey} type=\"button\" className={target ? 'is-selected' : ''} aria-pressed={Boolean(target)} onClick={() => toggleComparisonProvider(targetKey)}>\n                          <span className=\"dsh-ig-model-checkmark\">{target ? <Check size={12} /> : null}</span>\n                          <span className=\"dsh-ig-model-copy\"><strong>{item.label}</strong><small title={studioModelForMode(item, mode)}>{studioModelForMode(item, mode)}</small></span>\n                          {target && <span className=\"dsh-ig-model-settings\">{[target.ratio, target.resolution, target.quality === target.resolution ? undefined : target.quality, target.generationQuality === PROVIDER_DEFAULT_QUALITY ? undefined : target.generationQuality].filter(Boolean).join(' · ')}{target.adjusted ? <em>{t('compareAdjusted')}</em> : null}</span>}\n                        </button>\n                      )\n                    })}\n                  </div>\n                  <p>{t('compareParameterHint')}</p>\n                </div>\n                <div className=\"dsh-ig-field-grid is-output-grid\">\n                  <FieldSelect label={t('ratio')} value={ratio} onChange={setRatio} options={comparisonRatioOpts} />\n                  {comparisonResolutionOpts.length > 0 ? <FieldSelect label={lang === 'en' ? 'Resolution' : '分辨率'} value={comparisonResolution} onChange={setResolution} options={comparisonResolutionOpts} /> : null}\n                  {comparisonGenerationQualityOpts.length > 0 ? <FieldSelect label={lang === 'en' ? 'Generation quality' : '生成质量'} value={comparisonGenerationQuality} onChange={setGenerationQuality} options={comparisonGenerationQualityOpts} /> : null}\n                  <WatermarkControl capability={comparisonWatermarkCapability} value={watermark} onChange={setWatermark} lang={lang} />\n                </div>\n                {comparisonWatermarkCapability.status === 'supported' ? <div className=\"dsh-ig-inline-note\">{lang === 'en' ? 'Watermark applies only to models with confirmed support for this operation.' : '水印选项仅用于已确认支持当前操作的模型。'}</div> : null}\n                {comparisonTargets.some(target => target.profile.provider === 'chatgpt-sub') && <div className=\"dsh-ig-inline-note\">{t('subscriptionParameterHint')}</div>}\n              </> : <>\n                <div className=\"dsh-ig-field-grid\"><FieldSelect label={t('provider')} value={studioTargetKey(provider, channel)} onChange={changeProfile} options={config.providers.map(item => ({ value: studioTargetKey(item.provider, item.channel), label: `${item.label}${item.configured ? '' : ` · ${t('unconfigured')}`}` }))} /><FieldSelect label={t('model')} value={requestModel} onChange={setModel} options={activeProfile === undefined ? [] : studioModelOptionsForMode(activeProfile, mode)} /></div>\n                <div className=\"dsh-ig-field-grid is-output-grid\">\n                  <FieldSelect label={t('ratio')} value={ratio} onChange={setRatio} options={localizeRatioOptions(activeProfile?.ratioOptions ?? [], lang)} />\n                  {resolutionOpts.length > 0 ? <FieldSelect label={lang === 'en' ? 'Resolution' : '分辨率'} value={selectedResolution ?? ''} onChange={setResolution} options={resolutionOpts} /> : null}\n                  <FieldSelect label={['openai', 'chatgpt-sub', 'zhipu'].includes(provider) ? (lang === 'en' ? 'Generation quality' : '生成质量') : (lang === 'en' ? 'Resolution' : '分辨率')} value={selectedQuality} onChange={value => { setQuality(value); if (provider === 'openai') setGenerationQuality(value); else setResolution(value) }} options={provider === 'openai-compat' ? singleQualityOpts : localizeQualityOptions(singleQualityOpts, lang)} />\n                  {activeProfile?.generationQualityOptions ? <FieldSelect label={lang === 'en' ? 'Generation quality' : '生成质量'} value={selectedGenerationQuality} onChange={setGenerationQuality} options={localizeQualityOptions(activeProfile.generationQualityOptions, lang)} /> : null}\n                  <WatermarkControl capability={watermarkCapability} value={watermark} onChange={setWatermark} lang={lang} />\n                </div>\n                {provider === 'chatgpt-sub' && <div className=\"dsh-ig-inline-note\">{t('subscriptionParameterHint')}</div>}\n                <div className=\"dsh-ig-field\"><label>{t('count')}</label><div className=\"dsh-ig-count-row\">{[1, 2, 3, 4].map(option => <button key={option} type=\"button\" className={`dsh-ig-count-pill ${count === option ? 'is-active' : ''}`} onClick={() => setCount(option)}>{t('countUnit', { n: String(option) })}</button>)}</div></div>\n              </>}\n            </>}\n            {configuredCount === 0 && config !== null && <div className=\"dsh-ig-inline-note\">{t('noProvider')}</div>}\n            {error !== null && <div className=\"dsh-ig-form-error\">{error}</div>}\n            {isGenerating ? (\n              <button type=\"button\" className=\"dsh-ig-generate-button is-cancel\" onClick={cancelGeneration}>\n                <LoaderCircle className=\"dsh-ig-spin\" size={17} />\n                <span>{t('cancelGenerate')}</span>\n              </button>\n            ) : (\n              <button type=\"button\" className=\"dsh-ig-generate-button\" disabled={config === null} onClick={() => void submit()}>\n                <Sparkles size={17} />\n                <span>{comparisonEnabled ? `${t('compareStart')} (${comparisonTargets.length})` : `${t('start')}${count > 1 ? ` (${count})` : ''}`}</span>\n              </button>\n            )}\n          </div>\n        </aside>\n        )}\n      </div>\n\n      {/* Unified Pure Centered Lightbox Modal (Aligned with Gallery) */}\n      {lightboxOpen && selected !== null && (\n        <div className=\"dsh-ig-lightbox-backdrop\" onClick={() => setLightboxOpen(false)}>\n          <div className=\"dsh-ig-lightbox-topbar\">\n            <div className=\"dsh-ig-lightbox-meta\">\n              <span className=\"dsh-ig-tag\">{selected.provider}</span>\n              <span className=\"dsh-ig-tag dsh-ig-tag-model\">{selected.model}</span>\n              {currentBatch && currentBatch.length > 1 && (\n                <span className=\"dsh-ig-tag\">\n                  {currentBatch.findIndex(i => i.id === selected.id) + 1} / {currentBatch.length}\n                </span>\n              )}\n              {selected.attachment.width && selected.attachment.height ? (\n                <span className=\"dsh-ig-tag\">{selected.attachment.width} × {selected.attachment.height}</span>\n              ) : null}\n            </div>\n            <button\n              type=\"button\"\n              className=\"dsh-ig-lightbox-close-btn\"\n              title={t('close')}\n              onClick={() => setLightboxOpen(false)}\n            >\n              <X size={18} />\n            </button>\n          </div>\n\n          {currentBatch && currentBatch.length > 1 && (\n            <>\n              <button\n                type=\"button\"\n                className=\"dsh-ig-lightbox-nav is-prev\"\n                onClick={e => {\n                  e.stopPropagation()\n                  stepLightbox(-1)\n                }}\n                title=\"上一张\"\n              >\n                <ChevronLeft size={24} />\n              </button>\n              <button\n                type=\"button\"\n                className=\"dsh-ig-lightbox-nav is-next\"\n                onClick={e => {\n                  e.stopPropagation()\n                  stepLightbox(1)\n                }}\n                title=\"下一张\"\n              >\n                <ChevronRight size={24} />\n              </button>\n            </>\n          )}\n\n          <div className=\"dsh-ig-lightbox-img-wrap\" onClick={e => e.stopPropagation()}>\n            {image.url !== null ? (\n              <img\n                className=\"dsh-ig-lightbox-img\"\n                src={image.url}\n                alt={selected.prompt}\n              />\n            ) : (\n              <div className=\"dsh-ig-lightbox-loading\">\n                <div className=\"dsh-ig-lightbox-spinner\" />\n              </div>\n            )}\n          </div>\n\n          <div className=\"dsh-ig-lightbox-bottombar\" onClick={e => e.stopPropagation()}>\n            <div className=\"dsh-ig-lightbox-prompt-text\" title={selected.prompt}>\n              {selected.prompt}\n            </div>\n            <div className=\"dsh-ig-lightbox-actions\">\n              <button\n                type=\"button\"\n                className=\"dsh-ig-lightbox-btn\"\n                title={t('copyPpt')}\n                onClick={async () => {\n                  await navigator.clipboard.writeText(selected.prompt)\n                  flash(t('copiedPrompt'))\n                }}\n              >\n                <FileText size={14} />\n                <span>{t('copyPpt')}</span>\n              </button>\n\n              <button\n                type=\"button\"\n                className=\"dsh-ig-lightbox-btn\"\n                title={t('copy')}\n                onClick={async () => {\n                  if (!image.blob) return\n                  const ok = await copyImageBlob(image.blob)\n                  flash(ok ? t('copiedImage') : t('copyFailed'))\n                }}\n              >\n                <Copy size={14} />\n                <span>{t('copy')}</span>\n              </button>\n\n              <button\n                type=\"button\"\n                className=\"dsh-ig-lightbox-btn\"\n                title={t('download')}\n                onClick={downloadSelected}\n              >\n                <Download size={14} />\n                <span>{t('download')}</span>\n              </button>\n\n              <button\n                type=\"button\"\n                className={`dsh-ig-lightbox-btn ${saveSelectionComplete ? 'is-saved' : ''}`}\n                title={saveButtonLabel}\n                onClick={() => void handleSaveToGallery()}\n                disabled={saveSelectionComplete}\n              >\n                {saveSelectionComplete ? <Check size={14} /> : <BookmarkPlus size={14} />}\n                <span>{saveButtonLabel}</span>\n              </button>\n\n              <button\n                type=\"button\"\n                className=\"dsh-ig-lightbox-btn\"\n                title={selected.isFavorite ? t('favorited') : t('favorite')}\n                onClick={() => void toggleFavorite()}\n              >\n                <Heart size={14} fill={selected.isFavorite ? '#ef4444' : 'none'} color={selected.isFavorite ? '#ef4444' : 'currentColor'} />\n                <span>{selected.isFavorite ? t('favorited') : t('favorite')}</span>\n              </button>\n            </div>\n          </div>\n        </div>\n      )}\n\n      {showClearCanvasModal && (\n        <div className=\"dsh-ig-workbench-modal-backdrop\" onClick={() => setShowClearCanvasModal(false)}>\n          <div className=\"dsh-ig-workbench-modal-box\" role=\"dialog\" aria-modal=\"true\" aria-label={t('clearCanvas')} onClick={event => event.stopPropagation()}>\n            <div className=\"dsh-ig-workbench-modal-header\">\n              <AlertTriangle size={20} color=\"#dc2626\" /><strong>{t('clearCanvas')}</strong>\n            </div>\n            <p className=\"dsh-ig-workbench-modal-desc\">{t('clearCanvasDescription')}</p>\n            <div className=\"dsh-ig-workbench-modal-actions\">\n              <button autoFocus type=\"button\" className=\"dsh-ig-workbench-modal-cancel\" onClick={() => setShowClearCanvasModal(false)}>{t('cancel')}</button>\n              <button type=\"button\" className=\"dsh-ig-workbench-modal-danger\" onClick={() => {\n                try {\n                  if (!clearStudioTlCanvases()) { flash(t('loading')); return }\n                  setShowClearCanvasModal(false)\n                  flash(t('canvasCleared'))\n                } catch (error) {\n                  setError(messageOf(error))\n                  setShowClearCanvasModal(false)\n                }\n              }}>{t('clearCanvas')}</button>\n            </div>\n          </div>\n        </div>\n      )}\n\n      {/* Unified Deletion Danger Modal */}\n      {showDeleteModal && selected !== null && (\n        <div className=\"dsh-ig-workbench-modal-backdrop\" onClick={() => setShowDeleteModal(false)}>\n          <div className=\"dsh-ig-workbench-modal-box\" onClick={e => e.stopPropagation()}>\n            <div className=\"dsh-ig-workbench-modal-header\">\n              <AlertTriangle size={20} color=\"#dc2626\" />\n              <strong>{t('deleteModalTitle')}</strong>\n            </div>\n            <p className=\"dsh-ig-workbench-modal-desc\">{t('deleteModalDesc')}</p>\n            {Boolean(selected.savedTo) && (\n              <label className=\"dsh-ig-workbench-modal-option\">\n                <input\n                  type=\"checkbox\"\n                  checked={deleteWorkspaceFiles}\n                  onChange={e => setDeleteWorkspaceFiles(e.target.checked)}\n                />\n                <span>{t('deleteWorkspaceFilesLabel')}</span>\n              </label>\n            )}\n            <div className=\"dsh-ig-workbench-modal-actions\">\n              <button type=\"button\" className=\"dsh-ig-workbench-modal-cancel\" onClick={() => setShowDeleteModal(false)}>{t('cancel')}</button>\n              <button type=\"button\" className=\"dsh-ig-workbench-modal-danger\" onClick={() => void handleConfirmDelete()}>{t('confirm')}</button>\n            </div>\n          </div>\n        </div>\n      )}\n\n      {/* Unified Floating Toast */}\n      {notice !== null && <div className=\"dsh-ig-workbench-toast\">{notice}</div>}\n    </section>\n  )\n}\n"
    },
    {
      "path": "src/client/gif-comments.tsx",
      "content": "/**\n * Frame comments in the GIF lightbox: whether an animation can be edited and\n * with which model, the pins and note boxes over the frame (or over the sheet\n * of every frame), the editing toggle in the player bar, the card's edit chip,\n * the edit bar under the player, and what a send in progress and a finished\n * one show. The notes and the request live in gif-edit.tsx; this file owns\n * only the interaction.\n */\nimport { useEffect, useRef, useState, type KeyboardEvent, type MouseEvent } from 'react'\nimport { GIF_FRAME_COUNT_MAX, GIF_FRAME_COUNT_MIN, STUDIO_ROUTE, studioModelForMode, studioModelOptionsForMode, type StudioConfigResponse } from '../shared.js'\nimport type { GifT } from './gif-i18n.js'\nimport { useGifSnapshot, type GifPlayer, type GifPlayerSnapshot } from './gif-player.js'\nimport { GIF_COMMENTS_MAX, GIF_COMMENT_MAX_CHARS, sheetPinPosition, sheetViewSize, type GifComment, type GifSheetPlan } from './gif-sheet.js'\n\nexport type GifEditAvailability = 'ready' | 'frame-count' | 'unsupported' | 'decoding' | 'unloaded'\n\n/** A send in progress: the sheet and the model are being prepared, the model is redrawing, or the reply is in and the progress bar fills. */\nexport type GifEditPhase = 'preparing' | 'redrawing' | 'finishing'\n\n/** An edit that came back while its editor was on screen. */\nexport interface GifEditDone {\n  message: string\n  /** The channel answered with a still, which has no frames to leave notes on. */\n  still: boolean\n}\n\n/**\n * Whether the animation can be edited, and why not: only OpenAI-shaped\n * providers take the edit request, the frames must be decoded (the sheet is\n * built from them) and their number must be one the GIF contract can ask for.\n * Once decoded, the frames themselves are counted, whatever the header says:\n * they are what the sheet and the request use.\n */\nexport function gifEditAvailability(input: { provider: string; animated: boolean; snapshot: Pick<GifPlayerSnapshot, 'status' | 'frames' | 'info'> | undefined }): GifEditAvailability | undefined {\n  const { snapshot } = input\n  if (input.provider !== 'openai' && input.provider !== 'openai-compat') return undefined\n  if (!input.animated || snapshot === undefined) return undefined\n  const frames = snapshot.status === 'ready' ? snapshot.frames.length : snapshot.info?.frames\n  if (frames !== undefined && frames < GIF_FRAME_COUNT_MIN) return undefined\n  if (frames !== undefined && frames > GIF_FRAME_COUNT_MAX) return 'frame-count'\n  if (snapshot.status === 'fallback') return 'unsupported'\n  if (snapshot.status === 'native') return 'unloaded'\n  return snapshot.status === 'ready' ? 'ready' : 'decoding'\n}\n\nconst UNAVAILABLE_TITLE = { 'frame-count': 'gifEditTooManyFrames', unsupported: 'gifEditDecodeFailed', decoding: 'gifEditDecoding', unloaded: 'gifEditNotLoaded' } as const\n\n/**\n * The model for the edit: the channel's separate editing model when it has\n * one (the server takes nothing else for an edit); otherwise the model that\n * drew this animation while the channel still offers it, else the channel's\n * default; the card's own model when the channel is gone.\n */\nexport function gifEditModel(config: Pick<StudioConfigResponse, 'providers' | 'activeChannel'>, image: { provider: string; channel?: string | undefined; model: string }): string {\n  const channel = image.provider === 'openai-compat' ? image.channel ?? config.activeChannel : undefined\n  const profile = config.providers.find(candidate => candidate.provider === image.provider && (channel === undefined || candidate.channel === channel))\n  if (profile === undefined) return image.model\n  if (profile.editModel === undefined && studioModelOptionsForMode(profile, 'edit').some(option => option.value === image.model)) return image.model\n  return studioModelForMode(profile, 'edit')\n}\n\nexport async function fetchGifEditModel(image: { provider: string; channel?: string | undefined; model: string }, signal: AbortSignal): Promise<string> {\n  try {\n    const response = await fetch(STUDIO_ROUTE, { credentials: 'same-origin', signal })\n    if (!response.ok) return image.model\n    return gifEditModel(await response.json() as StudioConfigResponse, image)\n  } catch (cause) {\n    if (signal.aborted) throw cause\n    return image.model\n  }\n}\n\n/** What a key does in a note box: Enter confirms, Escape closes, and an input method still composing keeps every key. */\nexport function commentKeyAction(event: { key: string; nativeEvent: { isComposing: boolean } }): 'confirm' | 'close' | undefined {\n  if (event.nativeEvent.isComposing) return undefined\n  if (event.key === 'Escape') return 'close'\n  if (event.key === 'Enter') return 'confirm'\n  return undefined\n}\n\nconst PENCIL = <svg width=\"15\" height=\"15\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" strokeWidth=\"2\" strokeLinecap=\"round\" strokeLinejoin=\"round\" aria-hidden=\"true\"><path d=\"M12 20h9\" /><path d=\"M16.5 3.5a2.1 2.1 0 0 1 3 3L7 19l-4 1 1-4Z\" /></svg>\nconst SEND = <svg width=\"18\" height=\"18\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" strokeWidth=\"2.2\" strokeLinecap=\"round\" strokeLinejoin=\"round\" aria-hidden=\"true\"><path d=\"M12 19V5\" /><path d=\"M6 11l6-6 6 6\" /></svg>\nconst TRASH = <svg width=\"20\" height=\"20\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" strokeWidth=\"1.8\" strokeLinecap=\"round\" strokeLinejoin=\"round\" aria-hidden=\"true\"><path d=\"M4 7h16\" /><path d=\"M10 11v6M14 11v6\" /><path d=\"M6 7l1 12a2 2 0 0 0 2 2h6a2 2 0 0 0 2-2l1-12\" /><path d=\"M9 7V4h6v3\" /></svg>\n\n/** The card's edit chip, opposite the speed chip; it opens the lightbox straight in edit mode. */\nexport function GifEditChip({ availability, t, disabled, onOpen }: { availability: GifEditAvailability | undefined; t: GifT; disabled: boolean; onOpen(): void }) {\n  if (availability === undefined) return null\n  const ready = availability === 'ready'\n  return <div className=\"dsh-ig-gif-edit-chip-slot\">\n    <button\n      type=\"button\"\n      className=\"dsh-ig-gif-chip dsh-ig-gif-edit-chip\"\n      title={ready ? t('gifEditChipTitle') : t(UNAVAILABLE_TITLE[availability])}\n      disabled={!ready || disabled}\n      onClick={event => { event.stopPropagation(); onOpen() }}\n    >{PENCIL}<span>{t('gifEdit')}</span></button>\n  </div>\n}\n\n/** The player bar's editing switch. */\nexport function GifEditToggle({ availability, editing, t, onToggle }: { availability: GifEditAvailability; editing: boolean; t: GifT; onToggle(): void }) {\n  const title = editing ? t('gifEditExitTitle') : availability === 'ready' ? t('gifEditEnterTitle') : t(UNAVAILABLE_TITLE[availability])\n  // The label names the action, so the state is not announced as pressed too.\n  return <button type=\"button\" className={editing ? 'dsh-ig-gif-edit-toggle is-active' : 'dsh-ig-gif-edit-toggle'} title={title} disabled={!editing && availability !== 'ready'} onClick={onToggle}>{editing ? t('gifEditExitTitle') : t('gifEditToggle')}</button>\n}\n\nexport interface GifCommentBarProps {\n  view: 'gif' | 'sheet'\n  /** One-based frame on screen. */\n  current: number\n  total: number\n  count: number\n  phase: GifEditPhase | undefined\n  /** Whole seconds since the send. */\n  seconds: number\n  /** The answer to the request just sent. */\n  error?: string | undefined\n  /** What the error most likely means, when it came from the channel. */\n  errorHint?: string | undefined\n  t: GifT\n  onView(view: 'gif' | 'sheet'): void\n  onClear(): void\n  onSend(): void\n  onFallback(): void\n}\n\n/**\n * The edit bar under the player: what to do, the count, the view switch and\n * the actions. While a send runs it says what is happening and counts the\n * seconds. It has no cancel of its own: the player bar's switch leaves\n * editing, and the overlay on the picture stops a send.\n */\nexport function GifCommentBar({ view, current, total, count, phase, seconds, error, errorHint, t, onView, onClear, onSend, onFallback }: GifCommentBarProps) {\n  const sending = phase !== undefined\n  const fallback = <button type=\"button\" className=\"dsh-ig-gif-edit-ghost\" disabled={sending} onClick={onFallback}>{t('gifEditFallbackRegenerate')}</button>\n  const hint = phase === 'preparing' ? t('gifEditPreparingHint') : sending ? t('gifEditRedrawingHint') : view === 'sheet' ? t('gifEditSheetHint') : t('gifEditHint')\n  return <div className=\"dsh-ig-gif-edit\" onClick={event => { event.stopPropagation() }}>\n    <p className=\"dsh-ig-gif-edit-hint\">{hint}</p>\n    <div className=\"dsh-ig-gif-edit-row\">\n      <span className=\"dsh-ig-gif-edit-counter\">{view === 'sheet' ? t('gifSheetComments', { total: String(total), count: String(count) }) : t('gifFrameComments', { current: String(current), count: String(count) })}</span>\n      <div className=\"dsh-ig-gif-view\" role=\"group\" aria-label={t('gifEditView')}>\n        <button type=\"button\" aria-pressed={view === 'gif'} onClick={() => { onView('gif') }}>{t('gifGifView')}</button>\n        <button type=\"button\" aria-pressed={view === 'sheet'} onClick={() => { onView('sheet') }}>{t('gifSheetView')}</button>\n      </div>\n      <button type=\"button\" className=\"dsh-ig-gif-edit-ghost\" disabled={sending || count === 0} onClick={onClear}>{t('gifCommentsClear')}</button>\n      <button type=\"button\" className={sending ? 'dsh-ig-gif-edit-send is-busy' : 'dsh-ig-gif-edit-send'} disabled={sending || count === 0 || total === 0} onClick={onSend}>\n        {sending ? <><span className=\"dsh-ig-gif-edit-spinner\" aria-hidden=\"true\" />{phase === 'preparing' ? t('gifEditPreparing') : t('gifEditingSeconds', { seconds: String(seconds) })}</> : t('gifSend', { count: String(count) })}\n      </button>\n    </div>\n    {error !== undefined ? <div className=\"dsh-ig-gif-edit-error\" role=\"alert\"><strong>{t('gifEditFailed')}</strong>{errorHint !== undefined ? <span>{errorHint}</span> : null}<span>{error}</span>{fallback}</div> : null}\n  </div>\n}\n\n/**\n * Over the picture while a send runs, until its new version is filed; its\n * cancel is the one way to stop a send in the preview (the card has its own\n * once the preview is closed). It names the step but never a frame\n * (a note may ask to change every frame after it) and shows no number: the\n * redraw reports no progress, so the bar is an estimate that only the reply\n * fills.\n */\nexport function GifEditOverlay({ phase, progress, t, onCancel }: { phase: GifEditPhase; progress: number; t: GifT; onCancel(): void }) {\n  const finishing = phase === 'finishing'\n  return <div className={finishing ? 'dsh-ig-gif-edit-busy is-finishing' : 'dsh-ig-gif-edit-busy'} onClick={event => { event.stopPropagation() }}>\n    <span className=\"dsh-ig-gif-edit-busy-spinner\" aria-hidden=\"true\" />\n    <span className=\"dsh-ig-gif-edit-busy-text\" role=\"status\">{phase === 'preparing' ? t('gifEditPreparing') : t('gifEditRedrawing')}</span>\n    {phase === 'preparing' ? null : <span className=\"dsh-ig-gif-edit-busy-track\" aria-hidden=\"true\"><span className=\"dsh-ig-gif-edit-busy-fill\" style={{ transform: `scaleX(${String(progress)})` }} /></span>}\n    {finishing ? null : <button type=\"button\" className=\"dsh-ig-gif-edit-ghost\" onClick={onCancel}>{t('gifEditCancelSend')}</button>}\n  </div>\n}\n\n/**\n * Where the edit bar was, once an edit came back while it was watched: what\n * came of it, going on from the new version, or closing the preview. A new\n * animation takes notes once its frames are decoded; a still takes none.\n */\nexport function GifEditDoneBar({ done, availability, t, onContinue, onFinish }: { done: GifEditDone; availability: GifEditAvailability | undefined; t: GifT; onContinue?: (() => void) | undefined; onFinish(): void }) {\n  const ready = availability === 'ready' && onContinue !== undefined\n  return <div className=\"dsh-ig-gif-edit is-done\" onClick={event => { event.stopPropagation() }}>\n    <p className=\"dsh-ig-gif-edit-done-text\" role=\"status\">{done.message}</p>\n    <div className=\"dsh-ig-gif-edit-row is-end\">\n      {done.still ? null : <button type=\"button\" className=\"dsh-ig-gif-edit-ghost\" disabled={!ready} title={availability === undefined || availability === 'ready' ? undefined : t(UNAVAILABLE_TITLE[availability])} onClick={onContinue}>{t('gifEditContinue')}</button>}\n      <button type=\"button\" className=\"dsh-ig-gif-edit-send\" onClick={onFinish}>{t('gifEditFinish')}</button>\n    </div>\n  </div>\n}\n\nexport interface GifCommentLayerProps {\n  player: GifPlayer\n  editing: boolean\n  view: 'gif' | 'sheet'\n  /** Every frame tiled when editing began; shown scaled in the sheet view. */\n  sheet: { canvas: HTMLCanvasElement; plan: GifSheetPlan } | undefined\n  comments: readonly GifComment[]\n  onChange(comments: GifComment[]): void\n  t: GifT\n}\n\n/** A note box: a new note (no id yet), one being changed, or one being read outside editing. */\ninterface NoteBox {\n  mode: 'new' | 'edit' | 'view'\n  id?: number | undefined\n  frame: number\n  x: number\n  y: number\n  text: string\n  /** The box opens on the side of the pin with room for it, and above the pin near the bottom. */\n  left: boolean\n  up: boolean\n}\n\nconst NOTE_BOX_WIDTH = 292\nconst clampPercent = (value: number) => Math.round(Math.min(100, Math.max(0, value)) * 10) / 10\n\n/** Which side of a point a note box fits on, judged against the window: it may overhang the picture into the backdrop. */\nfunction noteSide(clientX: number, clientY: number): { left: boolean; up: boolean } {\n  const width = typeof window === 'undefined' ? Infinity : window.innerWidth\n  const height = typeof window === 'undefined' ? Infinity : window.innerHeight\n  return { left: clientX + 30 + NOTE_BOX_WIDTH > width - 16, up: clientY > height * 0.62 }\n}\n\n/**\n * Over the frame on screen: in editing, a layer that places a note on the\n * frame (pausing first), and that frame's pins; outside editing, the pins of a\n * paused frame, which open to read. In the sheet view every cell is a click\n * target and every pin is shown in its cell. Keys typed in a box stay in it:\n * Enter posts or saves, Escape closes only the box.\n */\nexport function GifCommentLayer({ player, editing, view, sheet, comments, onChange, t }: GifCommentLayerProps) {\n  const snapshot = useGifSnapshot(player)\n  const current = snapshot.index\n  const [box, setBox] = useState<NoteBox>()\n  const [boxKey, setBoxKey] = useState(0)\n  const canvasRef = useRef<HTMLCanvasElement>(null)\n  const inputRef = useRef<HTMLInputElement>(null)\n  // The layer, cell or pin that opened the box; focus goes back there when it closes.\n  const openerRef = useRef<HTMLElement | null>(null)\n  // The sheet's plan while the sheet view is on; its cells are the click targets then.\n  const plan = editing && view === 'sheet' ? sheet?.plan : undefined\n  const sheetView = plan !== undefined\n\n  useEffect(() => {\n    const canvas = canvasRef.current\n    if (!sheetView || sheet === undefined || canvas === null) return\n    canvas.getContext('2d')?.drawImage(sheet.canvas, 0, 0, canvas.width, canvas.height)\n  }, [sheetView, sheet])\n\n  // A box belongs to the view and the editing state it was opened in; leaving\n  // either, or the lightbox, keeps what was typed in it.\n  const leaveBox = useRef(() => {})\n  useEffect(() => () => { leaveBox.current() }, [editing, view])\n\n  const boxOpen = box !== undefined && box.mode !== 'view'\n  useEffect(() => {\n    if (boxOpen) inputRef.current?.focus()\n  }, [boxOpen, boxKey])\n\n  const open = (next: NoteBox, opener: HTMLElement) => {\n    openerRef.current = opener\n    setBox(next)\n    setBoxKey(key => key + 1)\n  }\n  const close = () => {\n    setBox(undefined)\n    // Back to the pin or cell that opened the box; not to the picture-wide layer, where Space would open another box instead of playing.\n    if (openerRef.current?.classList.contains('dsh-ig-gif-edit-layer') === false) openerRef.current.focus()\n    openerRef.current = null\n  }\n  const confirm = () => {\n    if (box === undefined || box.mode === 'view') return\n    const text = box.text.trim().slice(0, GIF_COMMENT_MAX_CHARS)\n    if (text.length === 0) return\n    if (box.mode === 'edit') {\n      const id = box.id\n      onChange(comments.map(comment => comment.id === id ? { ...comment, text } : comment))\n    } else {\n      onChange([...comments, { id: comments.reduce((max, comment) => Math.max(max, comment.id), 0) + 1, frame: box.frame, x: box.x, y: box.y, text }])\n    }\n    close()\n  }\n  const remove = () => {\n    if (box?.id !== undefined) onChange(comments.filter(comment => comment.id !== box.id))\n    close()\n  }\n  /** Moving on while a note is being written keeps what was typed rather than dropping it. */\n  const keepTyped = () => {\n    if (box !== undefined && box.mode !== 'view' && box.text.trim().length > 0) confirm()\n  }\n  leaveBox.current = () => {\n    keepTyped()\n    setBox(undefined)\n  }\n\n  /**\n   * A new note where the picture was clicked: on the frame on screen once the\n   * player is paused (a click while it plays stops it first), or on the cell's\n   * frame, which the player moves to so the pin is seen where it was put. A\n   * keyboard press has no point, so the note goes to the frame's centre. While\n   * a box is on screen a click only closes it, as a click outside any popover\n   * does; a box hidden by a frame change gives way, keeping what was typed.\n   */\n  const place = (frame: number | undefined, event: MouseEvent<HTMLElement>) => {\n    event.stopPropagation()\n    let count = comments.length\n    if (box !== undefined && box.mode !== 'view') {\n      const typed = box.text.trim().length > 0\n      if (typed) confirm()\n      else close()\n      if (onScreen(box.frame)) return\n      if (typed && box.mode === 'new') count += 1\n    }\n    if (count >= GIF_COMMENTS_MAX) return\n    if (frame === undefined) player.pause()\n    else player.seek(frame)\n    const rect = event.currentTarget.getBoundingClientRect()\n    const fromKeyboard = event.detail === 0\n    const clientX = fromKeyboard ? rect.left + rect.width / 2 : event.clientX\n    const clientY = fromKeyboard ? rect.top + rect.height / 2 : event.clientY\n    const x = clampPercent((clientX - rect.left) / rect.width * 100)\n    const y = clampPercent((clientY - rect.top) / rect.height * 100)\n    open({ mode: 'new', frame: frame ?? player.getSnapshot().index, x, y, text: '', ...noteSide(clientX, clientY) }, event.currentTarget)\n  }\n\n  const position = (comment: Pick<GifComment, 'frame' | 'x' | 'y'>) => plan !== undefined ? sheetPinPosition(comment, plan) : { x: comment.x, y: comment.y }\n  const pin = (comment: GifComment, number: number) => {\n    const at = position(comment)\n    const active = box?.id === comment.id\n    return <button\n      key={comment.id}\n      type=\"button\"\n      className={`dsh-ig-gif-pin${sheetView ? ' is-small' : ''}${active ? ' is-active' : ''}`}\n      style={{ left: `${String(at.x)}%`, top: `${String(at.y)}%` }}\n      title={sheetView ? t('gifCommentSheetTitle', { frame: String(comment.frame + 1), text: comment.text }) : t('gifCommentView')}\n      aria-label={t('gifCommentLabel', { index: String(number), frame: String(comment.frame + 1) })}\n      aria-expanded={active}\n      onClick={event => {\n        event.stopPropagation()\n        if (active) { close(); return }\n        keepTyped()\n        const rect = event.currentTarget.getBoundingClientRect()\n        open({ mode: editing ? 'edit' : 'view', id: comment.id, frame: comment.frame, x: comment.x, y: comment.y, text: comment.text, ...noteSide(rect.left, rect.top) }, event.currentTarget)\n      }}\n    >{number}</button>\n  }\n  // A pin and its box show only on their own frame; outside editing only while paused, as a playing frame changes too fast to read.\n  const onScreen = (frame: number) => sheetView || (frame === current && (editing || !snapshot.playing))\n  const pins = comments.flatMap((comment, index) => onScreen(comment.frame) ? [pin(comment, index + 1)] : [])\n\n  const noteBox = box === undefined || !onScreen(box.frame) ? null : (() => {\n    const at = position(box)\n    const number = box.id === undefined ? comments.length + 1 : comments.findIndex(comment => comment.id === box.id) + 1\n    const className = `dsh-ig-gif-note is-${box.mode}${box.left ? ' is-left' : ''}${box.up ? ' is-up' : ''}`\n    const style = { left: `${String(at.x)}%`, top: `${String(at.y)}%` }\n    if (box.mode === 'view') return <div className={className} role=\"dialog\" aria-label={t('gifCommentLabel', { index: String(number), frame: String(box.frame + 1) })} style={style} onClick={event => { event.stopPropagation() }}><p>{box.text}</p></div>\n    const empty = box.text.trim().length === 0\n    const input = <input\n      ref={inputRef}\n      type=\"text\"\n      className=\"dsh-ig-gif-note-input\"\n      aria-label={t('gifCommentPlaceholder')}\n      placeholder={t('gifCommentPlaceholder')}\n      maxLength={GIF_COMMENT_MAX_CHARS}\n      value={box.text}\n      onChange={event => { setBox({ ...box, text: event.target.value }) }}\n      onKeyDown={(event: KeyboardEvent<HTMLInputElement>) => {\n        // An input method keeps its keys, Escape included, so none reaches the lightbox.\n        if (event.nativeEvent.isComposing) { event.stopPropagation(); return }\n        if (commentKeyAction(event) !== 'confirm') return\n        event.preventDefault()\n        event.stopPropagation()\n        confirm()\n      }}\n    />\n    return <>\n      {box.mode === 'new' ? <span className={`dsh-ig-gif-pin is-draft${sheetView ? ' is-small' : ''}`} aria-hidden=\"true\" style={style}>{number}</span> : null}\n      <div\n        className={className}\n        role=\"dialog\"\n        aria-label={box.mode === 'new' ? t('gifCommentNew', { frame: String(box.frame + 1) }) : t('gifCommentEdit', { index: String(number) })}\n        style={style}\n        onClick={event => { event.stopPropagation() }}\n        // Focusable, so a click inside keeps the keys here rather than handing them to the player.\n        tabIndex={-1}\n        onKeyDown={event => {\n          event.stopPropagation()\n          if (commentKeyAction(event) !== 'close') return\n          event.preventDefault()\n          close()\n        }}\n      >\n        {box.mode === 'new'\n          ? <>{input}<button type=\"button\" className=\"dsh-ig-gif-note-post\" title={t('gifCommentPublishTitle')} aria-label={t('gifCommentPublish')} disabled={empty} onClick={confirm}>{SEND}</button></>\n          : <>\n            <div className=\"dsh-ig-gif-note-field\">{input}</div>\n            <div className=\"dsh-ig-gif-note-actions\">\n              <button type=\"button\" className=\"dsh-ig-gif-note-icon\" title={t('gifCommentDelete')} aria-label={t('gifCommentDelete')} onClick={remove}>{TRASH}</button>\n              <span />\n              <button type=\"button\" className=\"dsh-ig-gif-note-ghost\" onClick={close}>{t('gifEditCancel')}</button>\n              <button type=\"button\" className=\"dsh-ig-gif-note-save\" disabled={empty} onClick={confirm}>{t('gifCommentSave')}</button>\n            </div>\n          </>}\n      </div>\n    </>\n  })()\n\n  if (plan !== undefined) {\n    const viewSize = sheetViewSize(plan)\n    const cells = Array.from({ length: plan.cols * plan.rows }, (_, index) => {\n      const style = { left: `${String((index % plan.cols) / plan.cols * 100)}%`, top: `${String(Math.floor(index / plan.cols) / plan.rows * 100)}%`, width: `${String(100 / plan.cols)}%`, height: `${String(100 / plan.rows)}%` }\n      if (index >= plan.frames) return <div key={index} className=\"dsh-ig-gif-sheet-cell is-blank\" style={style} />\n      return <button\n        key={index}\n        type=\"button\"\n        className={`dsh-ig-gif-sheet-cell${index === current ? ' is-current' : ''}`}\n        aria-label={t('gifEditLayerLabel', { frame: String(index + 1) })}\n        style={style}\n        onClick={event => { place(index, event) }}\n      ><span>{index + 1}</span></button>\n    })\n    return <>\n      <canvas ref={canvasRef} className=\"dsh-ig-gif-sheet\" width={viewSize.width} height={viewSize.height} role=\"img\" aria-label={t('gifSheetView')} />\n      {cells}\n      {pins}\n      {noteBox}\n    </>\n  }\n  return <>\n    {editing ? <button\n      type=\"button\"\n      className=\"dsh-ig-gif-edit-layer\"\n      aria-label={t('gifEditLayerLabel', { frame: String(current + 1) })}\n      // A mouse click leaves focus alone, so Space still plays rather than activating the layer again.\n      onMouseDown={event => { event.preventDefault() }}\n      onClick={event => { place(undefined, event) }}\n    /> : null}\n    {pins}\n    {noteBox}\n  </>\n}\n"
    },
