      "path": "src/client/gif-edit.tsx",
      "content": "/**\n * Frame-comment editing of an animated card: the notes of each version, the\n * edit request that redraws the animation from them, and the lightbox that\n * hosts the editor. The card supplies its busy state, its version chain and\n * its regenerate dialog; gif-comments.tsx draws the editor.\n */\nimport { useEffect, useRef, useState, useSyncExternalStore, type MutableRefObject } from 'react'\nimport { STUDIO_ROUTE, type StudioGenerateRequest, type StudioGenerateResponse } from '../shared.js'\nimport { blobToDataUrl } from './browser-image-utils.js'\nimport type { ConversationImageRevision } from './conversation-image-revisions.js'\nimport type { RegeneratableImage } from './conversation-regenerate.js'\nimport { GifLightbox, type GifCard, type GifLightboxProps } from './gif-card.js'\nimport { GifCommentBar, GifCommentLayer, GifEditChip, GifEditDoneBar, GifEditOverlay, GifEditToggle, fetchGifEditModel, gifEditAvailability, type GifEditAvailability, type GifEditDone, type GifEditPhase } from './gif-comments.js'\nimport { composeFallbackPrompt, drawGifSheet, encodeSheetWithinLimit, gifEditRequest, planGifSheet, type GifComment, type GifSheetPlan } from './gif-sheet.js'\nimport { originalFromMeta } from './image-result-node.js'\nimport { readCanvasImageLimit } from './tl/canvas-selection.js'\n\nconst noSubscription = () => () => {}\n\n/**\n * The notes of each image version, by its attachment id: they outlive the card\n * (switching sessions or scrolling it away remounts it) and never mix between\n * images. Memory only; clearing a version's notes drops its entry.\n */\nconst notesByVersion = new Map<string, GifComment[]>()\n\n/** The workbench answered with an error, its own or the provider's; a request that never got an answer throws a plain Error. */\nclass StudioReplyError extends Error {}\n\n/** How long the reply waits before the new version is filed, so the bar is seen to fill (it takes .3s in gif-style.ts); the overlay stays until the version is filed. */\nexport const GIF_EDIT_FINISH_MS = 500\n\n/** How long the card says how an edit went when it came back unwatched: the user is busy elsewhere and may glance back late. */\nexport const GIF_EDIT_SENT_TOAST_MS = 8_000\n\n/** How long filing a new version waits for its picture: a fetch that stalls must not hold the version, or the overlay, back. */\nexport const GIF_EDIT_PREFETCH_WAIT_MS = 3_000\n\n/** Settles as `promise` does, or with undefined once `ms` have passed, whichever is first. */\nexport function waitAtMost<T>(promise: Promise<T>, ms: number): Promise<T | undefined> {\n  let timer: ReturnType<typeof setTimeout> | undefined\n  const timeout = new Promise<undefined>(resolve => { timer = setTimeout(() => { resolve(undefined) }, ms) })\n  return Promise.race([promise, timeout]).finally(() => { clearTimeout(timer) })\n}\n\n/**\n * The redraw's estimated share after waiting this long. The channel reports\n * no progress, so the estimate rises quickly at first, slows down, and never\n * passes 90%: only the reply fills the bar.\n */\nexport function gifEditProgressAt(waitedMs: number): number {\n  return 0.9 * (1 - Math.exp(-Math.max(0, waitedMs) / 25_000))\n}\n\nexport interface GifEditStatus {\n  phase: GifEditPhase | undefined\n  /** Whole seconds since the send; ticks every second until the reply. */\n  seconds: number\n  /** The redraw's estimated share, 0 to 1. */\n  progress: number\n  /** Kept until the user goes on from it, closes the preview or sends again. */\n  done: GifEditDone | undefined\n}\n\n/** One send's hold on the status; it does nothing once it ended, a later send began or the status was stopped. */\nexport interface GifEditRun {\n  redraw(): void\n  /** The reply is in: the bar fills and the seconds stop. */\n  finish(): void\n  /** Idle again, with what came of it when the editor is still on screen to show it. */\n  succeed(done: GifEditDone | undefined): void\n  stop(): void\n}\n\nexport interface GifEditStatusStore {\n  subscribe(listener: () => void): () => void\n  getSnapshot(): GifEditStatus\n  start(): GifEditRun\n  dismiss(): void\n  /** Stop ticking and drop the send in progress. */\n  stop(): void\n}\n\nconst IDLE: GifEditStatus = { phase: undefined, seconds: 0, progress: 0, done: undefined }\n\n/**\n * The card's send in progress and how the last one ended. It lives with the\n * card rather than the lightbox, which remounts when the new version loads,\n * and outside React state, so only the views that show the seconds re-render\n * every second.\n */\nexport function createGifEditStatus(): GifEditStatusStore {\n  let snapshot = IDLE\n  const listeners = new Set<() => void>()\n  let current: object | undefined\n  let startedAt = 0\n  let redrawAt = 0\n  let timer: ReturnType<typeof setInterval> | undefined\n  const set = (next: Partial<GifEditStatus>) => {\n    snapshot = { ...snapshot, ...next }\n    for (const listener of listeners) listener()\n  }\n  const seconds = () => Math.round((Date.now() - startedAt) / 1000)\n  const halt = () => {\n    clearInterval(timer)\n    timer = undefined\n  }\n  const end = () => {\n    halt()\n    current = undefined\n  }\n  return {\n    subscribe: listener => {\n      listeners.add(listener)\n      return () => { listeners.delete(listener) }\n    },\n    getSnapshot: () => snapshot,\n    start: () => {\n      halt()\n      const run = {}\n      current = run\n      startedAt = Date.now()\n      set({ ...IDLE, phase: 'preparing' })\n      timer = setInterval(() => {\n        set({ seconds: seconds(), progress: snapshot.phase === 'redrawing' ? gifEditProgressAt(Date.now() - redrawAt) : snapshot.progress })\n      }, 1000)\n      const live = () => current === run\n      return {\n        redraw: () => {\n          if (!live()) return\n          redrawAt = Date.now()\n          set({ phase: 'redrawing', progress: 0 })\n        },\n        finish: () => {\n          if (!live()) return\n          halt()\n          set({ phase: 'finishing', seconds: seconds(), progress: 1 })\n        },\n        succeed: done => {\n          if (!live()) return\n          end()\n          set({ ...IDLE, done })\n        },\n        stop: () => {\n          if (!live()) return\n          end()\n          set(IDLE)\n        },\n      }\n    },\n    dismiss: () => {\n      if (snapshot.done !== undefined) set({ done: undefined })\n    },\n    stop: () => {\n      end()\n      if (snapshot.phase !== undefined) set({ phase: undefined, seconds: 0, progress: 0 })\n    },\n  }\n}\n\n/** The sheet drawn when editing began, with the frame facts the request needs; it outlives frames the player releases. */\nexport interface DrawnSheet { canvas: HTMLCanvasElement; plan: GifSheetPlan; frame: { width: number; height: number; delaysMs: readonly number[] } }\n\nexport interface GifEditInput {\n  gif: GifCard\n  /** The version on display; editing is offered only for one the workbench can redraw. */\n  image: (RegeneratableImage & { prompt: string }) | undefined\n  /** Notes belong to the version they were made on. */\n  versionKey: string | undefined\n  /** The card's single busy slot, shared with regeneration: one request at a time, and the card's cancel aborts either. */\n  busy: { running: boolean; setRunning(running: boolean): void; controller: MutableRefObject<AbortController | undefined> }\n  /** File a new version under the card and in the gallery; resolves whether the gallery kept it. */\n  addRevision(revision: ConversationImageRevision): Promise<boolean>\n  /** The originating card's preview can stay open after the user leaves frame editing. */\n  isPreviewOpen(): boolean\n  /** The edit came back as a new version while its preview was closed. */\n  onSent(message: string): void\n  /** Regenerate from a description instead, with the notes written into the prompt. */\n  onFallback(prompt: string, hint: string): void\n}\n\nexport interface GifEdit {\n  t: GifCard['t']\n  availability: GifEditAvailability | undefined\n  comments: readonly GifComment[]\n  setComments(comments: GifComment[]): void\n  busy: boolean\n  /** The send in progress; the views that show its seconds subscribe to it. */\n  status: GifEditStatusStore\n  /** The reply is in and its version is being filed: there is nothing left to cancel. */\n  finishing: boolean\n  /** An edit that came back while its editor was on screen; the preview shows it in place of the edit bar. */\n  done: GifEditDone | undefined\n  dismissDone(): void\n  error: { message: string; fromChannel: boolean } | undefined\n  /** Said under the card title: a failure that came back while no editor was on screen. */\n  notice: string | undefined\n  /** The edit chip asked the next lightbox to open in edit mode. */\n  editRequested: boolean\n  requestEdit(): void\n  takeEditRequest(): boolean\n  /** The lightbox reports whether its editor is on screen, so a late failure knows where to show. */\n  setEditorOpen(open: boolean): void\n  beginEditing(): void\n  send(sheet: DrawnSheet): void\n  cancelSend(): void\n  fallback(total: number): void\n}\n\n/** The new version an edit reply describes, filed under the animation's own description rather than the sheet instructions. */\nfunction revisionFromReply(payload: StudioGenerateResponse, request: StudioGenerateRequest, prompt: string): ConversationImageRevision {\n  const original = originalFromMeta(payload.original)\n  return {\n    attachment: payload.attachment,\n    prompt,\n    provider: payload.provider,\n    ...(payload.channel === undefined ? {} : { channel: payload.channel }),\n    model: payload.model,\n    output: payload.output,\n    createdAt: payload.createdAt,\n    ratio: request.ratio,\n    quality: request.quality,\n    ...(request.resolution === undefined ? {} : { resolution: request.resolution }),\n    ...(request.generationQuality === undefined ? {} : { generationQuality: request.generationQuality }),\n    ...(request.watermark === undefined ? {} : { watermark: request.watermark }),\n    ...(original === undefined ? {} : { original }),\n  }\n}\n\n/** The notes of the version on display and the edit request built from them. */\nexport function useGifEdit({ gif, image, versionKey, busy, addRevision, isPreviewOpen, onSent, onFallback }: GifEditInput): GifEdit {\n  const { t, player } = gif\n  const [comments, setCommentsState] = useState<GifComment[]>(() => (versionKey === undefined ? [] : notesByVersion.get(versionKey) ?? []))\n  const [status] = useState(createGifEditStatus)\n  const readDone = () => status.getSnapshot().done\n  const done = useSyncExternalStore(status.subscribe, readDone, readDone)\n  const readFinishing = () => status.getSnapshot().phase === 'finishing'\n  const finishing = useSyncExternalStore(status.subscribe, readFinishing, readFinishing)\n  const [error, setError] = useState<{ message: string; fromChannel: boolean }>()\n  const [notice, setNotice] = useState<string>()\n  const [editRequested, setEditRequested] = useState(false)\n  const editorOpen = useRef(false)\n\n  useEffect(() => () => { status.stop() }, [])\n\n  // Notes point into the frames of one version: the version on display brings its own.\n  useEffect(() => {\n    setCommentsState(versionKey === undefined ? [] : notesByVersion.get(versionKey) ?? [])\n    setError(undefined)\n    setNotice(undefined)\n  }, [versionKey])\n\n  // A selector over the player, so the card re-renders when editing becomes possible, not on every frame.\n  const readAvailability = () => image === undefined || image.model.trim().length === 0\n    ? undefined\n    : gifEditAvailability({ provider: image.provider, animated: gif.animated, snapshot: player?.getSnapshot() })\n  const availability = useSyncExternalStore(player?.subscribe ?? noSubscription, readAvailability, readAvailability)\n\n  const setComments = (next: GifComment[]) => {\n    setCommentsState(next)\n    if (versionKey === undefined) return\n    if (next.length === 0) notesByVersion.delete(versionKey)\n    else notesByVersion.set(versionKey, next)\n  }\n\n  const send = (sheet: DrawnSheet) => {\n    if (image === undefined || player === undefined || busy.running || comments.length === 0) return\n    const controller = new AbortController()\n    busy.controller.current = controller\n    busy.setRunning(true)\n    setError(undefined)\n    setNotice(undefined)\n    const run = status.start()\n    // Either cancel, the overlay's or the card's, clears the overlay at once rather than when the step in flight notices.\n    controller.signal.addEventListener('abort', run.stop, { once: true })\n    void (async () => {\n      try {\n        const limit = await readCanvasImageLimit(controller.signal).catch(() => 4_000_000)\n        controller.signal.throwIfAborted()\n        const encoded = await encodeSheetWithinLimit(sheet.canvas, sheet.plan, limit).catch(() => { throw new Error(t('gifSheetTooLarge')) })\n        const data = (await blobToDataUrl(encoded.blob)).replace(/^[^,]*,/, '')\n        const model = await fetchGifEditModel(image, controller.signal)\n        const request = gifEditRequest({ image, model, comments, sheet: { mediaType: encoded.mediaType, data, plan: encoded.plan }, frame: sheet.frame, speed: player.getSnapshot().speed })\n        run.redraw()\n        const response = await fetch(STUDIO_ROUTE, {\n          method: 'POST',\n          credentials: 'same-origin',\n          signal: controller.signal,\n          headers: { 'content-type': 'application/json' },\n          body: JSON.stringify(request),\n        })\n        const payload = await response.json().catch(() => null) as StudioGenerateResponse | { error?: string } | null\n        if (!response.ok || payload === null || !('attachment' in payload)) {\n          const reported = payload !== null && 'error' in payload && payload.error ? payload.error : undefined\n          throw reported === undefined ? new Error(t('gifEditFailed')) : new StudioReplyError(reported)\n        }\n        run.finish()\n        // The reply is paid for: from here a cancel no longer drops it, and the full bar shows before the new version is filed.\n        await new Promise(resolve => { setTimeout(resolve, GIF_EDIT_FINISH_MS) })\n        const revision = revisionFromReply(payload, request, image.prompt)\n        const savedOk = await addRevision(revision)\n        if (controller.signal.aborted) return\n        // The channel answered with a still: kept as a version so the result is not lost.\n        const still = revision.original?.mediaType !== 'image/gif' && revision.attachment.mediaType !== 'image/gif'\n        if (!isPreviewOpen()) {\n          onSent(still ? t('gifEditStill') : savedOk ? t('gifEditDone') : t('gifEditSaveFailed'))\n          return\n        }\n        const message = still ? t('gifEditStill') : savedOk ? t('gifEditDoneHere', { seconds: String(status.getSnapshot().seconds) }) : t('gifEditSaveFailed')\n        run.succeed({ message, still })\n      } catch (cause) {\n        if (controller.signal.aborted) return\n        const message = (cause instanceof Error ? cause.message : String(cause)).slice(0, 300)\n        // Only an answer to the request says something about the channel; a\n        // sheet too large to encode or a dropped connection does not.\n        const fromChannel = cause instanceof StudioReplyError\n        // The edit bar shows it now or when it is opened again; with no editor on screen the card says it too.\n        setError({ message, fromChannel })\n        if (!editorOpen.current) setNotice(t('gifEditFailedNotice', { reason: message }))\n      } finally {\n        run.stop()\n        if (busy.controller.current === controller) {\n          busy.controller.current = undefined\n          busy.setRunning(false)\n        }\n      }\n    })()\n  }\n\n  return {\n    t,\n    availability,\n    comments,\n    setComments,\n    busy: busy.running,\n    status,\n    finishing,\n    done,\n    dismissDone: () => { status.dismiss() },\n    error,\n    notice,\n    editRequested,\n    requestEdit: () => { setEditRequested(true) },\n    takeEditRequest: () => {\n      if (!editRequested) return false\n      setEditRequested(false)\n      return true\n    },\n    setEditorOpen: open => { editorOpen.current = open },\n    beginEditing: () => {\n      setNotice(undefined)\n      status.dismiss()\n    },\n    send,\n    // Frees the card at once, as its own cancel does, rather than when the step in flight notices: the notes can be sent again straight away.\n    cancelSend: () => {\n      busy.controller.current?.abort()\n      busy.controller.current = undefined\n      busy.setRunning(false)\n    },\n    fallback: total => {\n      if (image === undefined) return\n      onFallback(composeFallbackPrompt(image.prompt, comments, total), t('gifEditFallbackHint'))\n    },\n  }\n}\n\n/** The card's edit chip, wired to open the lightbox in edit mode. */\nexport function GifCardEditChip({ edit, onOpen }: { edit: GifEdit; onOpen(): void }) {\n  return <GifEditChip availability={edit.availability} t={edit.t} disabled={edit.busy} onOpen={() => { edit.requestEdit(); onOpen() }} />\n}\n\n/** A failure that came back while no editor was on screen, under the card title. */\nexport function GifEditNotice({ edit }: { edit: GifEdit }) {\n  return edit.notice === undefined ? null : <div className=\"dsh-ig-gif-edit-notice\" role=\"status\">{edit.notice}</div>\n}\n\n/**\n * A finished edit in the plain image preview, which takes over when the new\n * version is a still, and for a moment while a new animation's bytes load.\n */\nexport function GifEditDoneDock({ edit, onFinish }: { edit: GifEdit; onFinish(): void }) {\n  if (edit.done === undefined) return null\n  return <div className=\"dsh-ig-gif-dock is-plain\" onClick={event => { event.stopPropagation() }}>\n    <GifEditDoneBar done={edit.done} availability={edit.availability} t={edit.t} onFinish={onFinish} />\n  </div>\n}\n\n/**\n * The GIF lightbox with the frame editor: entering edit mode pauses the\n * player and draws the sheet once (the sheet view and the request read it,\n * and it outlives frames the player releases); leaving it keeps the notes.\n * Escape leaves edit mode before it closes the lightbox. While a send runs the\n * picture is covered with its progress; an edit that comes back while the\n * editor is on screen leaves edit mode and shows the new version playing,\n * with its outcome where the edit bar was.\n */\nexport function GifEditLightbox({ edit, ...props }: GifLightboxProps & { edit: GifEdit }) {\n  const { player, gif } = props\n  const t = gif.t\n  const status = useSyncExternalStore(edit.status.subscribe, edit.status.getSnapshot, edit.status.getSnapshot)\n  const [editing, setEditing] = useState(false)\n  // The frame counter needs the frame only while editing, when the player is mostly paused.\n  const frameIndex = useSyncExternalStore(editing ? player.subscribe : noSubscription, () => (editing ? player.getSnapshot().index : 0), () => 0)\n  const [view, setView] = useState<'gif' | 'sheet'>('gif')\n  // Dropped, not cleared, on leaving: a send still encoding it holds its own reference.\n  const [sheet, setSheet] = useState<DrawnSheet>()\n  // Editing pauses on a frame; leaving it plays again if it was playing.\n  const playedBefore = useRef(false)\n  const enter = () => {\n    const current = player.getSnapshot()\n    const first = current.frames[0]\n    if (current.status !== 'ready' || first === undefined) return\n    playedBefore.current = current.playing\n    player.pause()\n    const plan = planGifSheet(current.frames.length, first.width, first.height)\n    setSheet({ canvas: drawGifSheet(current.frames, plan), plan, frame: { width: first.width, height: first.height, delaysMs: [...current.delaysMs] } })\n    setView('gif')\n    setEditing(true)\n    edit.beginEditing()\n  }\n  const leave = () => {\n    setEditing(false)\n    setSheet(undefined)\n    if (playedBefore.current) player.play()\n  }\n\n  useEffect(() => {\n    if (edit.takeEditRequest()) enter()\n  }, [])\n\n  useEffect(() => {\n    edit.setEditorOpen(editing)\n    return () => { edit.setEditorOpen(false) }\n  }, [editing])\n\n  // The paused frame and the sheet belonged to the version the edit replaced; the new one plays.\n  useEffect(() => {\n    if (edit.done === undefined) return\n    setEditing(false)\n    setSheet(undefined)\n  }, [edit.done])\n\n  useEffect(() => {\n    if (!editing) return\n    // Bubble phase on the document: a note box stops its own Escape first,\n    // and the card's window listener that closes the lightbox never sees this one.\n    const onKeyDown = (event: KeyboardEvent) => {\n      if (event.key !== 'Escape') return\n      event.stopPropagation()\n      leave()\n    }\n    document.addEventListener('keydown', onKeyDown)\n    return () => { document.removeEventListener('keydown', onKeyDown) }\n  }, [editing])\n\n  const clear = () => {\n    const count = edit.comments.length\n    if (count === 0 || !window.confirm(t('gifCommentsClearConfirm', { count: String(count) }))) return\n    edit.setComments([])\n  }\n\n  const frames = new Set(edit.comments.map(comment => comment.frame))\n  return <GifLightbox\n    {...props}\n    wrapClassName={editing ? (view === 'sheet' ? 'is-editing is-sheet' : 'is-editing') : undefined}\n    frameMarks={frames}\n    stageOverlay={<>\n      <GifCommentLayer player={player} editing={editing} view={view} sheet={sheet} comments={edit.comments} onChange={edit.setComments} t={t} />\n      {status.phase === undefined ? null : <GifEditOverlay phase={status.phase} progress={status.progress} t={t} onCancel={edit.cancelSend} />}\n    </>}\n    barTrailing={edit.availability === undefined ? null : <GifEditToggle availability={edit.availability} editing={editing} t={t} onToggle={() => { if (editing) leave(); else enter() }} />}\n    footer={editing ? <GifCommentBar\n      view={view}\n      current={frameIndex + 1}\n      total={sheet?.plan.frames ?? 0}\n      count={edit.comments.length}\n      phase={status.phase}\n      seconds={status.seconds}\n      error={edit.error?.message}\n      errorHint={edit.error?.fromChannel === true ? t('gifEditFailedHint') : undefined}\n      t={t}\n      onView={setView}\n      onClear={clear}\n      onSend={() => { if (sheet !== undefined) edit.send(sheet) }}\n      onFallback={() => { edit.fallback(sheet?.plan.frames ?? player.getSnapshot().frames.length) }}\n    /> : edit.done !== undefined ? <GifEditDoneBar done={edit.done} availability={edit.availability} t={t} onContinue={enter} onFinish={props.onClose} /> : null}\n  />\n}\n"
    },
    {
      "path": "src/config.ts",
      "content": "/** User-facing configuration for supported image providers. */\nimport z from '@deepseek-ai/schemastery'\nimport { compatEditFormat } from './watermark.js'\nimport type { CompatEditFormat } from './openai-compatible.js'\n\nimport {\n  ARK_BACKGROUND_MODES,\n  ARK_OUTPUT_FORMATS,\n  DEFAULT_CLOUD_TIMEOUT_MS,\n  DEFAULT_DASHSCOPE_ENDPOINT,\n  DEFAULT_DASHSCOPE_MODEL,\n  DEFAULT_COMFYUI_BASE_URL,\n  DEFAULT_COMFYUI_TIMEOUT_MS,\n  DEFAULT_COMFYUI_WORKFLOW_LABEL,\n  DEFAULT_GOOGLE_ENDPOINT,\n  DEFAULT_GOOGLE_MODEL,\n  DEFAULT_OPENAI_BASE_URL,\n  DEFAULT_OPENAI_MODEL,\n  DEFAULT_SEEDREAM_BASE_URL,\n  DEFAULT_SEEDREAM_MODEL,\n  currentSeedreamModel,\n  DEFAULT_SUBSCRIPTION_MODELS,\n  DEFAULT_XAI_BASE_URL,\n  DEFAULT_XAI_MODEL,\n  DEFAULT_ZHIPU_BASE_URL,\n  DEFAULT_ZHIPU_MODEL,\n  DASHSCOPE_API_KEY_ENV,\n  GOOGLE_API_KEY_ENV,\n  IMAGE_PROVIDERS,\n  OPENAI_API_KEY_ENV,\n  OPENAI_COMPAT_API_KEY_ENV,\n  SEEDREAM_API_KEY_ENV,\n  XAI_API_KEY_ENV,\n  ZHIPU_API_KEY_ENV,\n  activeComfyUIWorkflow,\n  resolveComfyUIWorkflows,\n  resolveOpenAICompatChannel,\n  type OpenAICompatChannel,\n  type ArkBackgroundMode,\n  type ArkOutputFormat,\n  type ArkOutputOptions,\n  type ComfyUIWorkflowEntry,\n  type ImageProvider,\n} from './shared.js'\n\nexport {\n  ARK_BACKGROUND_MODES,\n  ARK_OUTPUT_FORMATS,\n  DEFAULT_CLOUD_TIMEOUT_MS,\n  DEFAULT_DASHSCOPE_ENDPOINT,\n  DEFAULT_DASHSCOPE_MODEL,\n  DEFAULT_COMFYUI_BASE_URL,\n  DEFAULT_COMFYUI_TIMEOUT_MS,\n  DEFAULT_COMFYUI_WORKFLOW_LABEL,\n  DEFAULT_GOOGLE_ENDPOINT,\n  DEFAULT_GOOGLE_MODEL,\n  DEFAULT_OPENAI_BASE_URL,\n  DEFAULT_OPENAI_MODEL,\n  DEFAULT_SEEDREAM_BASE_URL,\n  DEFAULT_SEEDREAM_MODEL,\n  DEFAULT_XAI_BASE_URL,\n  DEFAULT_XAI_MODEL,\n  DEFAULT_ZHIPU_BASE_URL,\n  DEFAULT_ZHIPU_MODEL,\n  DASHSCOPE_API_KEY_ENV,\n  GOOGLE_API_KEY_ENV,\n  IMAGE_PROVIDERS,\n  OPENAI_API_KEY_ENV,\n  OPENAI_COMPAT_API_KEY_ENV,\n  SEEDREAM_API_KEY_ENV,\n  XAI_API_KEY_ENV,\n  ZHIPU_API_KEY_ENV,\n  activeComfyUIWorkflow,\n  resolveComfyUIWorkflows,\n  type ArkBackgroundMode,\n  type ArkOutputFormat,\n  type ArkOutputOptions,\n  type ComfyUIWorkflowEntry,\n  type ImageProvider,\n}\n\n/** Default workspace subfolder that receives generated image files. */\nexport const DEFAULT_WORKSPACE_FOLDER = 'dsh-image-gen'\n\n/** Google tool-level controls. Aligned with gemini-3.1-flash-image's common set. */\nexport const ASPECT_RATIOS = ['1:1', '3:2', '2:3', '4:3', '3:4', '4:5', '5:4', '16:9', '9:16', '21:9'] as const\nexport const IMAGE_SIZES = ['1K', '2K', '4K'] as const\nexport type AspectRatio = typeof ASPECT_RATIOS[number]\nexport type ImageSize = typeof IMAGE_SIZES[number]\n\n/** Bundle configuration from the profile patch and the Web settings page. */\nexport interface Config {\n  /** Opt in to public HTTPS:443 result downloads with pinned DNS and no redirects. */\n  strictImageDownloads?: boolean\n  /** Refuse web requests when the host connection admission service is absent. */\n  requireHostAdmission?: boolean\n  provider?: ImageProvider\n  cloudTimeoutMs?: number\n  googleModel?: string\n  googleEndpoint?: string\n  /** Use Gemini generateContent instead of Interactions; opt-in for native-only gateways. */\n  googleNative?: boolean\n  openaiBaseURL?: string\n  openaiModel?: string\n  /** Official model size table: ratio -> resolution tier -> pixels. Empty uses model presets. */\n  openaiSizes?: Record<string, Record<string, string>>\n  /** OpenAI-compatible relay settings; independent from the official OpenAI row. */\n  openaiCompatLabel?: string\n  openaiCompatBaseURL?: string\n  openaiCompatModel?: string\n  /** Models offered by the workbench for the legacy default channel. */\n  openaiCompatModels?: string[]\n  /** Additional named relay channels; the flat fields above remain the default channel. */\n  openaiCompatChannels?: OpenAICompatChannel[]\n  openaiCompatActiveChannel?: string\n  /** Editing model; empty reuses the generation model. */\n  openaiCompatEditModel?: string\n  /** Default quality; empty preserves the upstream default by omitting the field. */\n  openaiCompatQuality?: string\n  /** Quality values accepted by this relay; independent of resolution tiers. */\n  openaiCompatQualityOptions?: string[]\n  /** Generation-only JSON fields, merged last (e.g. watermark: false). */\n  openaiCompatExtraBody?: Record<string, unknown>\n  /** JSON edit sizing stays auto unless the relay supports selected dimensions. */\n  openaiCompatEditSizeMode?: 'auto' | 'selected'\n  /**\n   * Request shape the relay's images/edits endpoint expects (#41). Most\n    * relays take OpenAI's multipart form; some (e.g. SenseNova) accept the\n    * generations endpoint but run edits on their own JSON contract with\n    * `images: [{ image_url }]` objects; some take a multipart form whose\n    * `reference_images` field is a JSON array of base64 strings. Defaults to\n    * `multipart`.\n    */\n  openaiCompatEditFormat?: 'multipart' | 'jsonImageUrlArray' | 'formReferenceImages' | 'siliconflowJson'\n  /**\n   * Extra JSON fields merged into the JSON edit body last (can override the\n   * built-in defaults), e.g. SenseNova's `watermark`/`prompt_extend`.\n   * Used by JSON edit formats, including automatically recognized official contracts.\n   */\n  openaiCompatEditExtra?: Record<string, unknown>\n  /**\n   * Size table the OpenAI-compatible relay accepts, keyed\n   * `ratio → resolution tier → exact size string`, e.g.\n   * `{'16:9': {'1K': '1536x864', '2K': '2048x1152', '4K': '3840x2160'}}`.\n   * Empty keeps the built-in OpenAI trio (`1024x1024`, `1536x1024`,\n   * `1024x1536`). The workbench derives its ratio picker from the outer keys\n   * and its resolution picker from the tier keys, so relays or models with\n   * richer size tables expose every supported combination instead of the\n   * fixed three. Generation sends the exact configured string.\n   */\n  openaiCompatSizes?: Record<string, Record<string, string>>\n  seedreamBaseURL?: string\n  seedreamModel?: string\n  /**\n   * Ark `output_format`. Ark defaults to `jpeg`, which is lossy and cannot\n   * carry an alpha channel; `png` is lossless, so it survives later editing\n   * (e.g. background removal) without JPEG ringing around the subject.\n   */\n  seedreamOutputFormat?: ArkOutputFormat\n  /**\n   * Ark `watermark`. Ark defaults to `true`, which bakes an \"AI generated\"\n   * mark into the bottom-right corner.\n   */\n  seedreamWatermark?: boolean\n  /**\n   * Ark `background`. Only the edit path can honour `transparent`, and only\n   * when every reference image already carries an alpha channel.\n   */\n  seedreamBackground?: ArkBackgroundMode\n  dashscopeEndpoint?: string\n  dashscopeModel?: string\n  xaiBaseURL?: string\n  xaiModel?: string\n  zhipuBaseURL?: string\n  zhipuModel?: string\n  comfyuiBaseURL?: string\n  /** Named ComfyUI workflows managed by the Web settings page. */\n  comfyuiWorkflows?: ComfyUIWorkflowEntry[]\n  /** Name of the workflow ComfyUI calls use by default. */\n  comfyuiActiveWorkflow?: string\n  /** Legacy single-workflow storage; synced to the active entry for downgrades. */\n  comfyuiWorkflowJson?: string\n  /** Original imported file name of the legacy single workflow. */\n  comfyuiWorkflowName?: string\n  comfyuiTimeoutMs?: number\n  /** Also write every generated image as a file under the session workspace. */\n  saveToWorkspace?: boolean\n  /** Workspace subfolder for generated images; empty means the workspace root. */\n  workspaceFolder?: string\n  /** Show the provider switcher beside the chat input. */\n  showProviderPill?: boolean\n  /** Prune the host request-image cache once at startup and then daily. */\n  requestCachePrune?: boolean\n  /** Retain request-image variants for this many days. */\n  requestCacheTtlDays?: number\n  /** Byte budget for the request-image cache; 0 disables the cap. */\n  requestCacheMaxBytes?: number\n  /** Override the request-image cache root (empty keeps the DSH_HOME default). */\n  requestCacheDir?: string\n  /** Keep the pre-normalization bytes when the attachment layer changes an import or normalizes a generated GIF to a still. */\n  vaultEnabled?: boolean\n  /** Override the raw-image vault root (empty keeps the DSH_HOME default). */\n  vaultDir?: string\n}\n\n/**\n * Mark a schema field live for DSH 0.1.7+: the host serves a plugin's settings\n * form only for `.volatile()` fields and hands `apply` a `Volatile` box per\n * field (unwrapped in `src/index.ts`). Hosts ≤0.1.6 ship a schemastery without\n * the method, so marking is conditional — an unmarked schema stays plain there\n * and the old settings relay keeps working.\n */\nfunction volatile<T extends z>(schema: T): T {\n  const mark = (schema as unknown as { volatile?: () => T }).volatile\n  return typeof mark === 'function' ? mark.call(schema) : schema\n}\n\n/**\n * Cordis configuration schema. Volatile marking happens per field (see\n * `volatile`); the `z<Config>` annotation keeps the plain output type for the\n * rest of the codebase because the wrapping is unwrapped at the entry.\n */\nexport const Config = z.object({\n  provider: volatile(z.union(IMAGE_PROVIDERS).default('google')),\n  cloudTimeoutMs: volatile(z.number().min(5_000).max(3_600_000).default(DEFAULT_CLOUD_TIMEOUT_MS)),\n  strictImageDownloads: volatile(z.boolean().default(false)),\n  requireHostAdmission: volatile(z.boolean().default(false)),\n  googleModel: volatile(z.string().default(DEFAULT_GOOGLE_MODEL)),\n  googleEndpoint: volatile(z.string().default(DEFAULT_GOOGLE_ENDPOINT)),\n  googleNative: volatile(z.boolean().default(false)),\n  openaiBaseURL: volatile(z.string().default(DEFAULT_OPENAI_BASE_URL)),\n  openaiModel: volatile(z.string().default(DEFAULT_OPENAI_MODEL)),\n  openaiSizes: volatile(z.dict(z.dict(z.string())).default({})),\n  openaiCompatLabel: volatile(z.string().default('')),\n  openaiCompatBaseURL: volatile(z.string().default('')),\n  openaiCompatModel: volatile(z.string().default('')),\n  openaiCompatModels: volatile(z.array(z.string()).default([])),\n  openaiCompatChannels: volatile(z.array(z.object({\n    id: z.string(),\n    label: z.string().default(''),\n    keyRef: z.string(),\n    baseURL: z.string().default(''),\n    model: z.string().default(''),\n    models: z.array(z.string()).default([]),\n    editModel: z.string().default(''),\n    quality: z.string().default(''),\n    qualityOptions: z.array(z.string()).default([]),\n    extraBody: z.dict(z.any()).default({}),\n    editSizeMode: z.union(['auto', 'selected']).default('auto'),\n    editFormat: z.union([z.const('multipart'), z.const('jsonImageUrlArray'), z.const('formReferenceImages'), z.const('siliconflowJson')]).default('multipart'),\n    editExtra: z.dict(z.any()).default({}),\n    sizes: z.dict(z.dict(z.string())).default({}),\n  })).default([])),\n  openaiCompatActiveChannel: volatile(z.string().default('')),\n  openaiCompatEditModel: volatile(z.string().default('')),\n  openaiCompatQuality: volatile(z.string().default('')),\n  openaiCompatQualityOptions: volatile(z.array(z.string()).default(['auto', 'low', 'medium', 'high'])),\n  openaiCompatExtraBody: volatile(z.dict(z.any()).default({})),\n  openaiCompatEditSizeMode: volatile(z.union(['auto', 'selected']).default('auto')),\n  openaiCompatEditFormat: volatile(z.union([z.const('multipart'), z.const('jsonImageUrlArray'), z.const('formReferenceImages'), z.const('siliconflowJson')]).default('multipart')),\n  openaiCompatEditExtra: volatile(z.dict(z.any()).default({})),\n  openaiCompatSizes: volatile(z.dict(z.dict(z.string())).default({})),\n  seedreamBaseURL: volatile(z.string().default(DEFAULT_SEEDREAM_BASE_URL)),\n  seedreamModel: volatile(z.string().default(DEFAULT_SEEDREAM_MODEL)),\n  seedreamOutputFormat: volatile(z.union(ARK_OUTPUT_FORMATS).default('jpeg')),\n  seedreamWatermark: volatile(z.boolean().default(true)),\n  seedreamBackground: volatile(z.union(ARK_BACKGROUND_MODES).default('opaque')),\n  dashscopeEndpoint: volatile(z.string().default(DEFAULT_DASHSCOPE_ENDPOINT)),\n  dashscopeModel: volatile(z.string().default(DEFAULT_DASHSCOPE_MODEL)),\n  xaiBaseURL: volatile(z.string().default(DEFAULT_XAI_BASE_URL)),\n  xaiModel: volatile(z.string().default(DEFAULT_XAI_MODEL)),\n  zhipuBaseURL: volatile(z.string().default(DEFAULT_ZHIPU_BASE_URL)),\n  zhipuModel: volatile(z.string().default(DEFAULT_ZHIPU_MODEL)),\n  comfyuiBaseURL: volatile(z.string().default(DEFAULT_COMFYUI_BASE_URL)),\n  comfyuiWorkflows: volatile(z.array(z.object({ name: z.string(), json: z.string(), presetPrompt: z.string().default('') })).default([])),\n  comfyuiActiveWorkflow: volatile(z.string().default('')),\n  comfyuiWorkflowJson: volatile(z.string().default('')),\n  comfyuiWorkflowName: volatile(z.string().default('')),\n  comfyuiTimeoutMs: volatile(z.number().min(1_000).max(3_600_000).default(DEFAULT_COMFYUI_TIMEOUT_MS)),\n  saveToWorkspace: volatile(z.boolean().default(true)),\n  workspaceFolder: volatile(z.string().default(DEFAULT_WORKSPACE_FOLDER)),\n  showProviderPill: volatile(z.boolean().default(false)),\n  requestCachePrune: volatile(z.boolean().default(true)),\n  requestCacheTtlDays: volatile(z.number().min(1).max(365).default(14)),\n  requestCacheMaxBytes: volatile(z.number().min(0).default(256 * 1024 * 1024)),\n  requestCacheDir: volatile(z.string().default('')),\n  vaultEnabled: volatile(z.boolean().default(true)),\n  vaultDir: volatile(z.string().default('')),\n}) as unknown as z<Config>\n\n/** Resolve exactly one provider profile for a tool call. */\nexport function resolveProvider(config: Config):\n  | { provider: 'google'; apiKeyEnv: string; model: string; endpoint: string; native: boolean; aspectRatio: AspectRatio; imageSize: ImageSize }\n  | { provider: 'openai'; apiKeyEnv: string; model: string; baseURL: string; imageSize: string }\n  | { provider: 'openai-compat'; apiKeyEnv: string; model: string; baseURL: string; imageSize: string; editFormat: CompatEditFormat; editExtra: Record<string, unknown> }\n  | { provider: 'seedream'; apiKeyEnv: string; model: string; baseURL: string; imageSize: string; arkOptions: ArkOutputOptions }\n  | { provider: 'dashscope'; apiKeyEnv: string; model: string; endpoint: string; imageSize: string }\n  | { provider: 'xai'; apiKeyEnv: string; model: string; baseURL: string; imageSize: string }\n  | { provider: 'zhipu'; apiKeyEnv: string; model: string; baseURL: string; imageSize: string }\n  | { provider: 'comfyui'; baseURL: string; workflows: ComfyUIWorkflowEntry[]; workflow?: ComfyUIWorkflowEntry; timeoutMs: number }\n  | { provider: 'chatgpt-sub'; model: string }\n  | { provider: 'grok-sub'; model: string }\n  | { provider: 'google-sub'; model: string } {\n  switch (config.provider ?? 'google') {\n    case 'openai': return { provider: 'openai', apiKeyEnv: OPENAI_API_KEY_ENV, model: config.openaiModel ?? DEFAULT_OPENAI_MODEL, baseURL: config.openaiBaseURL ?? DEFAULT_OPENAI_BASE_URL, imageSize: '1024x1024' }\n    case 'openai-compat': {\n      const baseURL = config.openaiCompatBaseURL?.trim()\n      if (baseURL === undefined || baseURL.length === 0) {\n        throw new Error('OpenAI 兼容 provider requires a base URL; set it in Settings > Plugins > Image generation.')\n      }\n      const model = config.openaiCompatModel?.trim()\n      if (model === undefined || model.length === 0) {\n        throw new Error('OpenAI 兼容 provider requires a model name; set it in Settings > Plugins > Image generation.')\n      }\n      return { provider: 'openai-compat', apiKeyEnv: OPENAI_COMPAT_API_KEY_ENV, model, baseURL, imageSize: '1024x1024', editFormat: compatEditFormat(config), editExtra: config.openaiCompatEditExtra ?? {} }\n    }\n    case 'seedream': {\n      const seedreamBackground = config.seedreamBackground ?? 'opaque'\n      return {\n        provider: 'seedream',\n        apiKeyEnv: SEEDREAM_API_KEY_ENV,\n        model: currentSeedreamModel(config.seedreamModel),\n        baseURL: config.seedreamBaseURL ?? DEFAULT_SEEDREAM_BASE_URL,\n        imageSize: '2K',\n        arkOptions: {\n          // Ark rejects `output_format: jpeg` together with `background: transparent`\n          // outright — a JPEG cannot carry the alpha channel the transparent mode\n          // exists to produce. The two controls are independent in the settings UI,\n          // so couple them here rather than letting the combination reach the wire.\n          outputFormat: seedreamBackground === 'transparent' ? 'png' : config.seedreamOutputFormat ?? 'jpeg',\n          watermark: config.seedreamWatermark ?? true,\n          background: seedreamBackground,\n        },\n      }\n    }\n    case 'dashscope': return { provider: 'dashscope', apiKeyEnv: DASHSCOPE_API_KEY_ENV, model: config.dashscopeModel ?? DEFAULT_DASHSCOPE_MODEL, endpoint: config.dashscopeEndpoint ?? DEFAULT_DASHSCOPE_ENDPOINT, imageSize: '1024*1024' }\n    case 'xai': return { provider: 'xai', apiKeyEnv: XAI_API_KEY_ENV, model: config.xaiModel ?? DEFAULT_XAI_MODEL, baseURL: config.xaiBaseURL ?? DEFAULT_XAI_BASE_URL, imageSize: '1024x1024' }\n    case 'zhipu': return { provider: 'zhipu', apiKeyEnv: ZHIPU_API_KEY_ENV, model: config.zhipuModel ?? DEFAULT_ZHIPU_MODEL, baseURL: config.zhipuBaseURL ?? DEFAULT_ZHIPU_BASE_URL, imageSize: '1024x1024' }\n    case 'comfyui': {\n      const workflows = resolveComfyUIWorkflows(config)\n      const workflow = activeComfyUIWorkflow(config)\n      return {\n        provider: 'comfyui',\n        baseURL: config.comfyuiBaseURL ?? DEFAULT_COMFYUI_BASE_URL,\n        workflows,\n        ...(workflow === undefined ? {} : { workflow }),\n        timeoutMs: config.comfyuiTimeoutMs ?? DEFAULT_COMFYUI_TIMEOUT_MS,\n      }\n    }\n    case 'chatgpt-sub': return { provider: 'chatgpt-sub', model: DEFAULT_SUBSCRIPTION_MODELS['chatgpt-sub'] }\n    case 'grok-sub': return { provider: 'grok-sub', model: DEFAULT_SUBSCRIPTION_MODELS['grok-sub'] }\n    case 'google-sub': return { provider: 'google-sub', model: DEFAULT_SUBSCRIPTION_MODELS['google-sub'] }\n    case 'google': return { provider: 'google', apiKeyEnv: GOOGLE_API_KEY_ENV, model: config.googleModel ?? DEFAULT_GOOGLE_MODEL, endpoint: config.googleEndpoint ?? DEFAULT_GOOGLE_ENDPOINT, native: config.googleNative === true, aspectRatio: '1:1', imageSize: '1K' }\n  }\n}\n\n/** Project one named relay channel onto the legacy flat fields used by all provider adapters. */\nexport function withOpenAICompatChannel(config: Config, channelId?: string): Config {\n  const channel = resolveOpenAICompatChannel(config, channelId)\n  if (channel.id === 'default') return { ...config, openaiCompatActiveChannel: 'default' }\n  return {\n    ...config,\n    openaiCompatLabel: channel.label,\n    openaiCompatBaseURL: channel.baseURL,\n    openaiCompatModel: channel.model,\n    openaiCompatModels: channel.models ?? [],\n    openaiCompatEditModel: channel.editModel ?? '',\n    openaiCompatQuality: channel.quality ?? '',\n    openaiCompatQualityOptions: channel.qualityOptions ?? [],\n    openaiCompatExtraBody: channel.extraBody ?? {},\n    openaiCompatEditSizeMode: channel.editSizeMode ?? 'auto',\n    openaiCompatEditFormat: channel.editFormat ?? 'multipart',\n    openaiCompatEditExtra: channel.editExtra ?? {},\n    openaiCompatSizes: channel.sizes ?? {},\n    openaiCompatActiveChannel: channel.id,\n  }\n}\n\n/**\n * Apply a per-call provider and/or model override on top of the saved config.\n * `model` is ignored for ComfyUI, whose per-call equivalent is `workflow`.\n */\nexport function withProviderOverrides(config: Config, provider?: ImageProvider, model?: string, mode: 'generate' | 'edit' = 'generate'): Config {\n  const base: Config = provider === undefined ? { ...config } : { ...config, provider }\n  const trimmed = model?.trim() || (mode === 'edit' && base.provider === 'openai-compat' ? base.openaiCompatEditModel?.trim() : '') || ''\n  if (trimmed.length === 0) return base\n  switch (base.provider ?? 'google') {\n    case 'google': return { ...base, googleModel: trimmed }\n    case 'openai': return { ...base, openaiModel: trimmed }\n    case 'openai-compat': return { ...base, openaiCompatModel: trimmed, ...(mode === 'edit' ? { openaiCompatEditModel: trimmed } : {}) }\n    case 'seedream': return { ...base, seedreamModel: trimmed }\n    case 'dashscope': return { ...base, dashscopeModel: trimmed }\n    case 'xai': return { ...base, xaiModel: trimmed }\n    case 'zhipu': return { ...base, zhipuModel: trimmed }\n    // Subscription models are fixed by the bridge protocol; the override is ignored.\n    case 'chatgpt-sub': return base\n    case 'grok-sub': return base\n    case 'google-sub': return base\n    case 'comfyui': return base\n  }\n}\n\n/**\n * One-time migration: when the legacy single OpenAI slot points at a relay\n * (non-official base URL) and the compat row is empty, move the relay config\n * to the compat row so both can coexist. Returns the input untouched when\n * nothing needs moving.\n */\nexport function migrateOpenAICompatConfig(config: Config): Config {\n  const legacyBase = config.openaiBaseURL?.trim() ?? ''\n  if (legacyBase.length === 0 || legacyBase === DEFAULT_OPENAI_BASE_URL) return config\n  if (hostOf(legacyBase) === 'api.openai.com') return config\n  if ((config.openaiCompatBaseURL?.trim() ?? '').length > 0) return config\n  const compatModel = config.openaiCompatModel?.trim() ?? ''\n  return {\n    ...config,\n    openaiCompatBaseURL: legacyBase,\n    ...(compatModel.length > 0 ? {} : { openaiCompatModel: config.openaiModel }),\n    ...((config.openaiCompatModels?.length ?? 0) > 0 ? {} : { openaiCompatModels: [compatModel || config.openaiModel?.trim() || ''].filter(Boolean) }),\n    openaiBaseURL: DEFAULT_OPENAI_BASE_URL,\n    ...(config.provider === 'openai' ? { provider: 'openai-compat' as const } : {}),\n  }\n}\n\n/** Host part of a URL, or null when it cannot be parsed. */\nfunction hostOf(raw: string): string | null {\n  try {\n    return new URL(raw).host\n  } catch {\n    return null\n  }\n}\n\n/** The workflow a ComfyUI call runs: